KG_CODE("f:src/autoskill/desktop/actions.py","\"\"\"Desktop actions.\n\nDesign rule that shapes every function here: **prefer the semantic pattern over\nthe mouse**. UIA exposes `Invoke`, `Toggle`, `Select`, `SetValue`; using them is\nboth more reliable than a synthetic click at a coordinate and safer, because the\naction lands on the element that was resolved rather than on whatever happens to\nbe under that pixel now. A coordinate click is the fallback, never the default.\n\nEvery action returns an `EffectState`. That is not bookkeeping — it is the\ndifference between an agent that retries safely and one that sends the same\nmessage twice.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport os\nimport subprocess\nimport time\nfrom contextlib import contextmanager, nullcontext\nfrom contextvars import ContextVar\nfrom pathlib import Path\nfrom typing import Any, Callable\n\nfrom ..hidden import hidden\nfrom ..protocol import EffectState, ErrorCode, ProtocolError, InteractiveRequired\nfrom . import overlay\nfrom .refs import ElementRef, RefStore, has_drifted\n\ntry:\n    import uiautomation as auto\nexcept ImportError:  # pragma: no cover\n    auto = None  # type: ignore\n\n\ndef _overlay_aim(x: int | None, y: int | None) -> None:\n    \"\"\"Glide the agent cursor to the action target before real input lands.\n\n    Pure decoration, fail-open twice over: overlay.aim swallows everything\n    internally, and the extra try/except here means even an import-time\n    catastrophe cannot reach the action. The arrival wait inside is capped\n    (~0.3 s), so a wedged overlay never delays automation.\n    \"\"\"\n    if x is None or y is None:\n        return\n    try:\n        overlay.aim(x, y)\n    except Exception:\n        pass\n\ndef _overlay_pin_above(hwnd: int | None) -> None:\n    \"\"\"b4o: pin the overlay above the driven window's root on every aim\n    (CUA pin_overlay_above: GA_ROOT of the target before each action).\"\"\"\n    if not hwnd:\n        return\n    try:\n        overlay.pin_above(hwnd)\n    except Exception:\n        pass\n\n\ndef _overlay_aim_rect(entry: ElementRef) -> None:\n    \"\"\"Aim the overlay at a driver-observed ref: SDK frames are screen\n    coordinates (UIA BoundingRectangle cached by the walk; the screenshot\n    remap runs only when a screenshot was requested, which ours never are),\n    so the rect centre is the screen point, exactly like the Python path's\n    control centre.\"\"\"\n    r = entry.rect\n    if r is not None and r[2] > r[0]:\n        # b4of item 1: pin BEFORE the glide (CUA impl_.rs:3685-3686,\n        # :6993-6994, :7360-7361) so the cursor never glides behind the\n        # target - the owner's symptom.\n        _overlay_pin_above(entry.top_window)\n        _overlay_aim((r[0] + r[2]) // 2, (r[1] + r[3]) // 2)\n        try:\n            overlay.say(entry.name or entry.role, \"aiming\")\n        except Exception:\n            pass\n\n\ndef _overlay_aim_ref(entry: ElementRef) -> None:\n    r = _safe(lambda: entry.control.BoundingRectangle, None)\n    if r is not None and r.right > r.left:\n        # b4of item 1: pin BEFORE the glide (as the driver path above).\n        _overlay_pin_above(entry.top_window)\n        _overlay_aim((r.left + r.right) // 2, (r.top + r.bottom) // 2)\n        try:\n            overlay.say(entry.name or entry.role, \"aiming\")\n        except Exception:\n            pass\n\n\ndef _overlay_pulse(verified: bool = False) -> None:\n    \"\"\"Record action activity without displaying unverified completion.\"\"\"\n    try:\n        overlay.pulse()\n        overlay.say(\"\", \"done\" if verified else \"verifying\")\n    except Exception:\n        pass\n\n\ndef _require_uia() -> Any:\n    if auto is None:\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"uiautomation is not installed\",\n                            hint=\"pip install uiautomation\")\n    return auto\n\n\ndef _safe(fn, default=None):\n    try:\n        return fn()\n    except Exception:\n        return default\n\n\ndef _guard(entry: ElementRef) -> None:\n    \"\"\"Refuse to act on an element that changed since it was observed.\"\"\"\n    drift = has_drifted(entry)\n    if drift:\n        raise ProtocolError(\n            ErrorCode.STALE_REF,\n            f\"{entry.ref} cannot be used: {drift}\",\n            hint=\"Run `auto observe` again and use a fresh ref.\")\n    if not entry.enabled:\n        raise ProtocolError(\n            ErrorCode.TARGET_DISABLED,\n            f\"{entry.describe()} is disabled\",\n            hint=\"Something must enable it first; observe to find what.\")\n\n\ndef _result(effect: EffectState, **extra: Any) -> dict[str, Any]:\n    return {\"effect_state\": effect.value, **extra}\n\n\n# Owner decision (handoff section 3 item 7): AutoSkill never refuses an\n# action because the target runs at a higher integrity level; it attempts\n# the delivery and reports the observed result honestly (never a false\n# success). When the advisory integrity read says the target is elevated,\n# the posted-route result carries exactly this sentence as information.\n_INTEGRITY_NOTE = (\"target runs at a higher integrity level; Windows may \"\n                   \"drop the input unless AutoSkill runs at that level\")\n\n\ndef _virtual_screen() -> tuple[int, int, int, int]:\n    \"\"\"Bounds of all monitors combined, as (left, top, right, bottom).\"\"\"\n    try:\n        import ctypes\n        u = ctypes.windll.user32\n        left, top = u.GetSystemMetrics(76), u.GetSystemMetrics(77)\n        width, height = u.GetSystemMetrics(78), u.GetSystemMetrics(79)\n        return left, top, left + width, top + height\n    except Exception:\n        return -10_000, -10_000, 10_000, 10_000\n\n\ndef _require_on_screen(x: int, y: int, entry: ElementRef) -> None:\n    \"\"\"Refuse a coordinate click whose point is not on any monitor.\n\n    A desktop click moves the real mouse, so an off-screen point does not\n    merely fail — it can land on whatever else occupies that spot, or be\n    swallowed entirely while we report success. Minimised windows report\n    coordinates like (-31280, -31564); partially off-screen ones are subtler\n    and would not trip the drift heuristic.\n    \"\"\"\n    left, top, right, bottom = _virtual_screen()\n    if left <= x <= right and top <= y <= bottom:\n        return\n    raise ProtocolError(\n        ErrorCode.TARGET_NOT_VISIBLE,\n        f\"{entry.describe()} is at ({x}, {y}), outside the visible desktop \"\n        f\"({left},{top} to {right},{bottom})\",\n        hint=\"The window is probably minimised or moved off-screen. Restore \"\n             \"it (`auto focus --window \\\"#handle\\\"`), then observe and retry.\")\n\n\n# Some desktop work genuinely cannot avoid the foreground: Windows sends\n# synthetic keystrokes and real mouse events to whatever is in front, and a\n# region screenshot captures whatever pixels are there. What it CAN do is put\n# the screen back afterwards, so working alongside the tool costs a flicker\n# instead of a buried window. The user owns this through `steal_focus`.\nRESTORE_FOREGROUND = True\nBACKGROUND_ONLY: ContextVar[bool] = ContextVar(\"desktop_background_only\", default=False)\n\n\ndef require_interactive(operation: str, *, code: str = \"background_needs_physical_input\",\n                        driver_reason: str | None = None) -> None:\n    \"\"\"Never silently turn a background operation into shared desktop input.\"\"\"\n    if BACKGROUND_ONLY.get():\n        raise InteractiveRequired(\n            f\"{operation} requires interactive desktop input\",\n            hint=\"Quiet mode keeps the user's focus, pointer and clipboard untouched. \"\n                 \"Use an observed element's UIA pattern or an application API; \"\n                 \"Enable desktop_interactive_fallback for shared desktop input.\",\n            code=code, driver_reason=driver_reason)\n\n\nFALLBACK_DISABLED_HINT = (\"No input was sent. The one-time interactive fallback is off; \"\n                          \"the user can turn it on with \"\n                          \"`auto config set desktop-interactive-fallback on`.\")\n\n\ndef deliver(action: Callable[[], dict[str, Any]], *, quiet: bool,\n            interactive_fallback: bool, annotate: bool = False,\n            restore_foreground: bool = True) -> dict[str, Any]:\n    \"\"\"Prefer quiet delivery; switch once only on a pre-input capability decline.\n\n    CUA input/delivery.rs separates semantic and physical capabilities. Reuse\n    our own action handlers, refs and worker; never replay an unknown mutation.\n\n    With `annotate` (desktop actions), every result says how it was delivered:\n    `requested_delivery` (quiet or interactive, from the user's steal-focus\n    setting) and `delivery` (background, interactive, or interactive-fallback\n    with `fallback_reason`), as Cua Driver records requested and actual\n    delivery separately (cua-driver-core action_record.rs). A refusal that\n    cannot fall back says why and how the user can allow it.\n    \"\"\"\n    token = BACKGROUND_ONLY.set(quiet)\n    requested = \"quiet\" if quiet else \"interactive\"\n    try:\n        try:\n            result = action()\n            if annotate and isinstance(result, dict):\n                result = {**result, \"requested_delivery\": requested,\n                          \"delivery\": \"background\" if quiet else \"interactive\",\n                          \"route\": result.get(\"via\") or\n                          (\"background\" if quiet else \"interactive\")}\n            return result\n        except InteractiveRequired as exc:\n            eligible = quiet and interactive_fallback and exc.error.effect_state == EffectState.NONE\n            if not eligible:\n                if annotate and quiet and not interactive_fallback:\n                    exc.error.hint = f\"{exc.error.hint or ''} {FALLBACK_DISABLED_HINT}\".strip()\n                    details = dict(exc.error.details or {})\n                    refusal = dict(details.get(\"delivery_refusal\") or {})\n                    refusal[\"fallback\"] = \"disabled\"\n                    details[\"delivery_refusal\"] = refusal\n                    exc.error.details = details\n                raise\n            reason = {\"code\": getattr(exc, \"code\", \"background_needs_physical_input\"),\n                      \"message\": exc.error.message}\n        BACKGROUND_ONLY.set(False)\n        # b14: a request whose effect IS the foreground (desktop.focus, CUA's bring_to_front) is not handed back.\n        with (foreground_returned() if restore_foreground else nullcontext()):\n            result = action()\n        return {**result, \"requested_delivery\": requested, \"delivery\": \"interactive-fallback\",\n                \"fallback_reason\": reason, \"quiet\": False,\n                \"route\": result.get(\"via\") or \"interactive-fallback\"}\n    finally:\n        BACKGROUND_ONLY.reset(token)\n\n\ndef _foreground_handle() -> int:\n    try:\n        import ctypes\n        return int(ctypes.windll.user32.GetForegroundWindow())\n    except Exception:\n        return 0\n\n\ndef _cursor_pos() -> tuple[int, int] | None:\n    try:\n        import ctypes\n        from ctypes import wintypes\n        pt = wintypes.POINT()\n        if ctypes.windll.user32.GetCursorPos(ctypes.byref(pt)):\n            return (pt.x, pt.y)\n        return None\n    except Exception:\n        return None\n\n\n@contextmanager\ndef foreground_returned():\n    \"\"\"Take the foreground if the work needs it, then hand it back.\n\n    Not cosmetic. The alternative is that every click in an unattended run\n    buries the window someone is typing in.\n    \"\"\"\n    prev = _foreground_handle() if RESTORE_FOREGROUND and not BACKGROUND_ONLY.get() else 0\n    # The Kgrow.io dashboard stays on top of every window; for a physical step\n    # it turns invisible and click-through, so a real click lands on the\n    # target and a screen capture does not read the dashboard (dashboard/windows.py).\n    from ..dashboard.windows import make_way\n    way = make_way() if not BACKGROUND_ONLY.get() else nullcontext()\n    try:\n        with way:\n            yield\n    finally:\n        if prev and RESTORE_FOREGROUND and _foreground_handle() != prev:\n            try:\n                _force_foreground(prev)\n            except Exception:\n                pass\n\n\ndef _foreground_title() -> str:\n    try:\n        import ctypes\n        hwnd = ctypes.windll.user32.GetForegroundWindow()\n        buf = ctypes.create_unicode_buffer(320)\n        ctypes.windll.user32.GetWindowTextW(hwnd, buf, 320)\n        return buf.value\n    except Exception:\n        return \"\"\n\n\ndef _owning_window(entry: ElementRef) -> int:\n    \"\"\"The top-level window to raise before real input on `entry`.\n\n    A ref's own `window_handle` is 0 for windowless UIA elements (most Office,\n    WPF, UWP and browser controls), which made interactive typing, keys and the\n    physical click target `#0` and fail (CM-47). Observations now record the\n    observed window as `top_window`; that is preferred.\n    \"\"\"\n    owning = getattr(entry, \"owning_window\", None)\n    if callable(owning):\n        return int(owning() or 0)\n    return int(getattr(entry, \"window_handle\", 0) or 0)\n\n\ndef _window_selector(entry: ElementRef) -> str | None:\n    handle = _owning_window(entry)\n    return f\"#{handle}\" if handle else None\n\n\ndef _aim_keyboard(window: str | None) -> str:\n    \"\"\"Decide — and report — which window is about to receive keystrokes.\n\n    Keyboard input with no element target goes to whatever holds focus, and\n    nothing here used to check what that was. Measured: `Ctrl+Shift+N` and\n    three folder names intended for File Explorer were typed into the chat\n    window that happened to be in front, and every call still reported\n    `committed`.\n\n    Typing into the wrong application is worse than not typing at all, so a\n    caller that names a window gets it raised and verified first, and a caller\n    that does not is at least told where the keys landed.\n    \"\"\"\n    require_interactive(\"Keyboard targeting\")\n    if window:\n        w = find_window(window)\n        if w is None:\n            raise ProtocolError(\n                ErrorCode.WINDOW_NOT_FOUND,\n                f\"no window matching {window!r} to type into\",\n                hint=\"Run `auto windows` and target it by #handle.\")\n        _raise_and_verify(w, window)\n        return _safe(lambda: w.Name, \"\") or window\n    return _foreground_title()\n\n\n# --- activation --------------------------------------------------------------\n\ndef _expand_if_collapsed(pattern: Any) -> None:\n    \"\"\"Expand a collapsed control, refusing to fake a click on an open one.\n\n    A left click on a combobox that is already open *closes* it. `Expand()` on\n    an open box is a silent no-op, so reporting it as the click's effect would\n    be a lie — decline the pattern and let the physical path do the real thing.\n    \"\"\"\n    # ExpandCollapseState: 0 collapsed, 1 expanded, 2 partial, 3 leaf.\n    if _safe(lambda: int(pattern.ExpandCollapseState), 0) == 1:\n        raise ValueError(\"already expanded\")\n    pattern.Expand()\n\n\ndef focus(store: RefStore, ref: str) -> dict[str, Any]:\n    require_interactive(\"Focusing an element\")\n    entry = store.resolve(ref)\n    _guard(entry)\n    if entry.control is None and entry.element_token:\n        return _focus_driver_ref(entry)\n    ok = _safe(lambda: (entry.control.SetFocus(), True)[1], False)\n    if not ok:\n        raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                            f\"could not focus {entry.describe()}\")\n    return _result(EffectState.COMMITTED, target=entry.describe())\n\n\ndef _focus_driver_ref(entry: ElementRef) -> dict[str, Any]:\n    \"\"\"sw1: a driver ref has no live element. CUA focuses its cached element the same way before foreground typing\n    (impl_.rs:4531-4567 at 815dfd96): owning window in front, UIA SetFocus, keyboard focus read back within 350 ms.\n    The element is the one at the observed centre whose rect and top-level window are the observed ones; no click\n    fallback (CUA clicks only before typing into a field - here it would press buttons).\"\"\"\n    r = entry.rect\n    if not entry.top_window or r is None or r[2] <= r[0]:\n        raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                            f\"could not focus {entry.describe()}: it has no observed position\")\n    focus_window(f\"#{entry.top_window}\")\n    hit = _safe(lambda: _require_uia().ControlFromPoint((r[0] + r[2]) // 2, (r[1] + r[3]) // 2), None)\n    for _ in range(5):\n        b = _safe(lambda: hit.BoundingRectangle, None) if hit is not None else None\n        if b is None or (b.left, b.top, b.right, b.bottom) == r:\n            break\n        hit = _safe(lambda: hit.GetParentControl(), None)\n    else:\n        b = None\n    if b is None or _safe(lambda: hit.GetTopLevelControl().NativeWindowHandle, 0) != entry.top_window:\n        raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                            f\"could not focus {entry.describe()}: it is not at its observed position\",\n                            hint=\"Scroll it into view (desktop.scroll), observe again and focus the fresh ref.\")\n    _safe(lambda: hit.SetFocus())\n    deadline = time.monotonic() + 0.35\n    while not _safe(lambda: bool(hit.HasKeyboardFocus), False):\n        if time.monotonic() >= deadline:\n            raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                                f\"Windows did not confirm keyboard focus on {entry.describe()}\",\n                                hint=\"The element may not take focus; click it, or focus its window.\")\n        time.sleep(0.01)\n    return _result(EffectState.COMMITTED, target=entry.describe(), via=\"uia-setfocus\")\n\n\ndef _driver_effect(effect: str, evidence: list | None = None) -> EffectState:\n    \"\"\"SDK ActionEffect -> AutoSkill effect_state. `confirmed` with a\n    non-empty evidence array is CUA's own \"publishable readback\" invariant\n    (action-result-contract.md: \"confirmed has publishable readback or\n    window-change evidence\"). Ack-only dispatch (unverifiable/partial) and\n    a suspected no-op are honest UNKNOWN. The old `verified` boolean is\n    dead (the contract removed it); K2c removes the dependency.\"\"\"\n    if effect == \"confirmed\" and evidence:\n        return EffectState.COMMITTED\n    return EffectState.UNKNOWN\n\n\ndef _driver_action(entry: ElementRef, method: str, params: dict[str, Any],\n                   *, verb: str,\n                   pixel_params: Any = None,\n                   first: str = \"background\") -> dict[str, Any] | None:\n    \"\"\"One driver element-token action with the 0.6.3 delivery policy.\n\n    Background first. A retryable background refusal routes through DR-02:\n    `require_interactive` raises in quiet mode, so `deliver()` applies the\n    owner's desktop-interactive-fallback before this rung re-issues exactly\n    once with delivery_mode foreground. Non-retryable refusals and anything\n    after possible dispatch (unknown/committed) are final and never replayed.\n    A pre-dispatch unavailable driver falls back to the caller's Python rungs\n    only when the ref carries a control; token-only refs refuse honestly.\n    \"\"\"\n    # O5 (plan section 9): every driver action result carries observed\n    # foreground/cursor changes over the action window - from immediately\n    # before the first SDK call to after the final reply (the wrapper below\n    # reads after the DR-02 foreground re-issue too, because the inner\n    # function returns only when the delivery is settled). These booleans\n    # state OBSERVED changes during the action window. They are not\n    # attribution: a human may move the mouse meanwhile.\n    fg_before = _foreground_handle()\n    cursor_before = _cursor_pos()\n    res = _driver_action_inner(entry, method, params, verb=verb,\n                               pixel_params=pixel_params, first=first)\n    if res is None:\n        return None\n    res[\"foreground_changed\"] = _foreground_handle() != fg_before\n    res[\"cursor_moved\"] = _cursor_pos() != cursor_before\n    return res\n\n\ndef _driver_action_inner(entry: ElementRef, method: str,\n                         params: dict[str, Any],\n                         *, verb: str,\n                         pixel_params: Any = None,\n                         first: str = \"background\") -> dict[str, Any] | None:\n    from . import driver_backend\n\n    def call(delivery: str) -> dict[str, Any] | None:\n        if pixel_params is not None:\n            # b5t3: CUA's capture-bound pixel click - no element_token; each\n            # call takes its OWN fresh capture, so a DR-02 foreground\n            # re-issue never replays the ID consumed at admission (OQ-B2).\n            return driver_backend.try_call(\n                method, {**pixel_params(), \"delivery_mode\": delivery})\n        return driver_backend.try_call(\n            method, {**params, \"element_token\": entry.element_token,\n                     \"delivery_mode\": delivery})\n\n    # b9: `first` is \"foreground\" only for a caller already in interactive\n    # mode (the key route); every other caller keeps background first.\n    reply = call(first)\n    if reply is None:\n        if entry.control is not None:\n            return None  # caller's Python rungs; nothing was dispatched\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"{entry.ref} is a driver observation ref and the driver is \"\n            \"unavailable; no input was sent\",\n            hint=\"Re-run the action when the driver is available, or observe \"\n                 \"with AUTOSKILL_DRIVER=off to use Python refs.\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        code = str(error.get(\"code\", \"driver_error\"))\n        state = error.get(\"effect_state\")\n        # I3: the adapter sends CUA's own predicate results as additive\n        # booleans (wants_foreground, stale_element).\n        wants_fg = bool(error.get(\"wants_foreground\"))\n        stale_el = bool(error.get(\"stale_element\"))\n        if state == \"none\" and wants_fg and first == \"background\":\n            # DR-02: the quiet route declined before dispatching input.\n            # CUA's wants_foreground predicate (batch_tools.rs:1344-1366,\n            # ported in the adapter) produced effect_state \"none\" and the\n            # foreground escalation marker. The opt-in is the owner's call,\n            # made by deliver() — never here. The reason carries CUA's\n            # live message text from the SDK reply; the driver's code is\n            # preserved even when not in REFUSAL_CODES (K4 fix).\n            sdk_reason = str(error.get(\"message\", \"\")) or code\n            require_interactive(f\"driver {verb}: {sdk_reason}\", code=code,\n                             driver_reason=sdk_reason)\n            retry = call(\"foreground\")\n            if retry is not None and retry.get(\"ok\"):\n                return _driver_result(entry, retry[\"result\"], verb,\n                                      delivery=\"foreground\")\n            if retry is not None and not retry.get(\"ok\"):\n                error = retry.get(\"error\") or {}\n                code = str(error.get(\"code\", code))\n                state = error.get(\"effect_state\", state)\n            else:\n                code, state = \"driver_unavailable_after_refusal\", \"none\"\n        if stale_el:\n            # CUA's stale_element predicate (batch_tools.rs:1370-1394):\n            # code or refusal.code is element_outside_target_window or\n            # stale_element_token, or the message carries those strings\n            # or \"-25202\" — all decided by the adapter, not re-checked here.\n            raise ProtocolError(\n                ErrorCode.STALE_REF,\n                f\"{entry.ref} is stale in the driver's snapshot\",\n                hint=\"Run `auto observe` again and use a fresh ref.\")\n        # CUA's live message from the SDK reply is the authoritative reason;\n        # it flows unchanged into delivery_refusal.reason when DR-02 applies.\n        sdk_message = str(error.get(\"message\", \"\"))\n        unknown = state == \"unknown\"\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused {verb} on {entry.ref}: {code}: {sdk_message}\",\n            hint=(\"Inspect the current state before retrying.\" if unknown\n                  else \"The refusal happened before any input; respect it \"\n                       \"or ask the user.\"),\n            effect_state=EffectState.UNKNOWN if unknown else EffectState.NONE)\n    return _driver_result(entry, reply[\"result\"], verb, delivery=first)\n\n\ndef _driver_result(entry: ElementRef, result: dict[str, Any], verb: str,\n                   *, delivery: str) -> dict[str, Any]:\n    effect = str(result.get(\"effect\", \"unverifiable\"))\n    evidence = result.get(\"evidence\")\n    path = str(result.get(\"path\", \"ax\"))\n    committed = effect == \"confirmed\" and bool(evidence)\n    # I7: CUA's ActionResult fields surface additively inside `driver`\n    # (plan 0.3 rule 4), copied unchanged and only when the SDK sent\n    # them (the contract's serde attrs skip absent keys). CUA's\n    # delivery object lands under `sdk_delivery`; `driver.delivery`\n    # keeps its AutoSkill meaning (background/foreground). `path` is\n    # not a CUA field (outputs.rs:681-699 has none), so it always\n    # defaults to \"ax\" — observed, not touched (owner decision).\n    driver = {\"path\": path, \"delivery\": delivery, \"effect\": effect}\n    for key in (\"route\", \"evidence\", \"escalation\", \"summary\"):\n        if key in result:\n            driver[key] = result[key]\n    if \"delivery\" in result:\n        driver[\"sdk_delivery\"] = result[\"delivery\"]\n    return _result(_driver_effect(effect, evidence), method=verb,\n                   via=f\"driver-{path}\",\n                   verified=committed,\n                   driver=driver)\n\n\ndef _pixel_click_ref(entry: ElementRef, *, double: bool = False,\n                     right: bool = False, count: int | None = None,\n                     button: str | None = None,\n                     modifier: list[str] | None = None,\n                     delivery_mode: str | None = None) -> dict[str, Any]:\n    \"\"\"b5t3 (B5 T3): `--real` on a driver ref = CUA's capture-bound pixel\n    click (impl_.rs:3356, admission :3579-3609). Right before dispatch -\n    after any approval, which the daemon asks before the handler runs - a\n    FRESH native capture is taken (capture_for_action, OQ-B2); the ref's\n    screen-frame centre is mapped into that screenshot's pixels with CUA's\n    own origin (element_frame.rs; the DWM frame + 1 px, impl_.rs:227-249,\n    when the reply carried no element frames); CUA admits and consumes the\n    capture_id. The real pointer returns afterwards (M1, _saved_cursor).\"\"\"\n    r = entry.rect\n    if r is None or not r[2] > r[0] or not r[3] > r[1]:\n        raise ProtocolError(\n            ErrorCode.TARGET_NOT_VISIBLE,\n            f\"{entry.describe()} has no frame for a pixel click\",\n            hint=\"Observe again; a pixel click needs the element's frame.\",\n            effect_state=EffectState.NONE)\n    centre = ((r[0] + r[2]) / 2.0, (r[1] + r[3]) / 2.0)\n    _overlay_aim_rect(entry)\n    res = pixel_click(entry, entry.window_pid, entry.top_window,\n                      screen_point=centre,\n                      count=count if count is not None else (2 if double else None),\n                      button=button if button is not None else (\"right\" if right else None),\n                      modifier=modifier, delivery_mode=delivery_mode)\n    if res is None:\n        # try_call None before any dispatch (a token ref has no Python rung).\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"{entry.ref} is a driver observation ref and the driver is \"\n            \"unavailable; no input was sent\",\n            effect_state=EffectState.NONE)\n    return res\n\n\ndef pixel_click(entry: Any, pid: int, hwnd: int, *,\n                screen_point: tuple[float, float] | None = None,\n                zoom_point: tuple[float, float] | None = None,\n                local_point: tuple[float, float] | None = None,\n                count: int | None = None, button: str | None = None,\n                modifier: list[str] | None = None,\n                check_inside: bool = False,\n                delivery_mode: str | None = None) -> dict[str, Any] | None:\n    \"\"\"b5t3/b5t45: CUA's pixel click on one window, shared by `click --real`\n    and `click_at` (impl_.rs:3341-3362 schema; dispatch :4148-4185).\n\n    screen_point: a FRESH native capture is taken right before dispatch\n    (capture_for_action, OQ-B2); the point maps into its pixels with CUA's\n    own origin (the reply's frame/screenshot_frame pair, else the DWM frame\n    + 1 px, impl_.rs:227-249) and the click carries its capture_id.\n    zoom_point: x/y are pixels of the last zoom image (from_zoom), no\n    capture (CUA refuses capture_id with from_zoom, :3584). local_point (p3r\n    D3): x/y are already window-local capture pixels - the fresh capture's\n    capture_id, no origin arithmetic. count / button /\n    modifier pass through as CUA's own keys. Each delivery attempt builds\n    fresh params, so a DR-02 foreground re-issue never replays a consumed\n    capture. The real pointer returns afterwards (M1). None = the driver was\n    unavailable before any input.\"\"\"\n    from . import captures\n    session = f\"pixel-click:{pid}:{hwnd}\"\n\n    def params() -> dict[str, Any]:\n        out: dict[str, Any] = {\"pid\": int(pid), \"window_id\": int(hwnd)}\n        if zoom_point is not None:\n            out.update(x=zoom_point[0], y=zoom_point[1], from_zoom=True)\n        else:\n            # fx2: window-local pixels belong to the last image of the window,\n            # so the fresh capture is taken at that image's size.\n            size = captures.image_size(hwnd) if local_point is not None else None\n            cap = captures.capture_for_action(session, pid, hwnd,\n                                              max_image_dimension=max(size) if size else 0)\n            origin = (0, 0) if local_point is not None else getattr(cap, \"frame_origin\", None)\n            if origin is None:\n                frame = captures._dwm_frame(hwnd)\n                if frame is None:\n                    raise ProtocolError(\n                        ErrorCode.WINDOW_NOT_FOUND,\n                        \"The target window cannot be resolved\",\n                        effect_state=EffectState.NONE)\n                origin = (frame[0] + 1, frame[1] + 1)\n            point = local_point if local_point is not None else screen_point\n            x = round(point[0] - origin[0])\n            y = round(point[1] - origin[1])\n            if check_inside and not (0 <= x < (cap.width or 0)\n                                     and 0 <= y < (cap.height or 0)):\n                raise ProtocolError(\n                    ErrorCode.TARGET_NOT_VISIBLE,\n                    f\"({point[0]:.0f}, {point[1]:.0f}) is \"\n                    \"outside the target window's capture\",\n                    hint=\"Coordinates from `auto ocr --window` are screen \"\n                         \"coordinates; pass --relative only for \"\n                         \"window-local ones.\",\n                    effect_state=EffectState.NONE)\n            out.update(x=x, y=y, capture_id=cap.capture_id)\n        if count is not None:\n            out[\"count\"] = int(count)\n        if button is not None:\n            out[\"button\"] = str(button)\n        if modifier:\n            out[\"modifier\"] = [str(m) for m in modifier]\n        return out\n\n    first = _first_delivery(delivery_mode)\n    with _saved_cursor():\n        res = _driver_action(entry, \"click\", {}, verb=\"click\",\n                             pixel_params=params, first=first)\n    if res is not None:\n        _overlay_pulse(verified=bool(res.get(\"verified\")))\n    return res\n\n\ndef _first_delivery(delivery_mode: str | None) -> str:\n    \"\"\"p3h: CUA click's own delivery_mode key (impl_.rs:3341-3362). Foreground passes the owner's interactive gate\n    first (quiet mode: refused, or DR-02's one-time fallback when enabled); absent means CUA's background default.\"\"\"\n    if delivery_mode == \"foreground\":\n        require_interactive(\"Foreground click\")\n        return \"foreground\"\n    return \"background\"\n\n\ndef click(store: RefStore, ref: str, *, double: bool = False,\n          right: bool = False, real: bool = False,\n          count: int | None = None, button: str | None = None,\n          modifier: list[str] | None = None,\n          delivery_mode: str | None = None,\n          action: str | None = None) -> dict[str, Any]:\n    with foreground_returned():\n        return _click(store, ref, double=double, right=right, real=real,\n                      count=count, button=button, modifier=modifier,\n                      delivery_mode=delivery_mode, action=action)\n\n\ndef _click(store: RefStore, ref: str, *, double: bool = False,\n          right: bool = False, real: bool = False,\n          count: int | None = None, button: str | None = None,\n          modifier: list[str] | None = None,\n          delivery_mode: str | None = None,\n          action: str | None = None) -> dict[str, Any]:\n    entry = store.resolve(ref)\n    _guard(entry)\n    explicit = count is not None or button is not None or bool(modifier) or bool(action)\n    if action and (real or not entry.element_token):\n        # fx3: CUA's click action is an accessibility action on an element\n        # token (impl_.rs:3344-3355); a pixel or Python click has none.\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"{entry.ref}: --action {action} needs the driver's element click (not --real, not a Python ref)\",\n            hint=\"Observe with the driver available and use its ref.\",\n            effect_state=EffectState.NONE)\n    if entry.element_token:\n        if real:\n            return _pixel_click_ref(entry, double=double, right=right,\n                                    count=count, button=button,\n                                    modifier=modifier, delivery_mode=delivery_mode)\n        click_params: dict[str, Any] = {}\n        method = \"click\"\n        if explicit:\n            # b5t45 (T5, closes B3's section-G gap): CUA's own click keys\n            # (impl_.rs:3359-3361; the adapter's element mode gates them).\n            # --double/--right fold in only when the explicit key is absent.\n            if count is not None:\n                click_params[\"count\"] = int(count)\n            elif double:\n                click_params[\"count\"] = 2\n            if button is not None:\n                click_params[\"button\"] = str(button)\n            elif right:\n                click_params[\"button\"] = \"right\"\n            if modifier:\n                click_params[\"modifier\"] = [str(m) for m in modifier]\n            if action:\n                click_params[\"action\"] = str(action)   # fx3: CUA's \"expand\"\n        elif double and right:\n            # Both flags together stay CUA's click (the adapter remaps to\n            # count:2 + button:\"right\"): the dedicated tools have no\n            # count/button vocabulary (schemas impl_.rs:6901-6911 and\n            # :7268-7278 at the pin) - a deliberate mapping, not an\n            # oversight.\n            click_params[\"double\"] = True\n            click_params[\"right\"] = True\n        elif double:\n            # b4c: --double alone uses CUA's dedicated double_click tool,\n            # which scrolls an off-screen element into view before posting\n            # (resolve_onscreen_point_with_scroll, impl_.rs:106-182); its\n            # schema requires pid alongside the token.\n            method, click_params = \"double_click\", {\"pid\": entry.window_pid}\n        elif right:\n            # b4c: --right alone uses CUA's dedicated right_click tool\n            # (same scroll-into-view resolver; schema requires pid).\n            method, click_params = \"right_click\", {\"pid\": entry.window_pid}\n        _overlay_aim_rect(entry)\n        res = _driver_action(entry, method, click_params, verb=\"click\",\n                             first=_first_delivery(delivery_mode))\n        if res is not None:\n            _overlay_pulse(verified=bool(res.get(\"verified\")))\n            return res\n    if explicit and not (count in (None, 1, 2) and button in (None, \"left\", \"right\")\n                         and not modifier):\n        # The Python rungs click once/twice with the left or right button\n        # only; a triple click, the middle button or held modifiers have no\n        # Python rung - refused before any input, never approximated.\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"{entry.ref}: count/button/modifier beyond single, double, \"\n            \"left and right need the driver's click\",\n            hint=\"Observe with the driver available and use its ref.\",\n            effect_state=EffectState.NONE)\n    if count == 2:\n        double = True\n    if button == \"right\":\n        right = True\n    ctl = entry.control\n    _overlay_aim_ref(entry)\n\n    # 1. Semantic activation. Which pattern counts as \"a click\" depends on the\n    #    role, and getting the order wrong is not a stylistic matter:\n    #    `Invoke` on a list item means *open it*, not *select it*. Clicking a\n    #    file row to give the list keyboard focus therefore launched the file\n    #    instead — a real side effect from what should have been a selection.\n    #\n    #    `real=True` skips this phase entirely. Measured on Windows 11\n    #    save/rename dialogs (ledger R26): UIA Invoke *reports success* while\n    #    the dialog does nothing — the pattern call goes through, the button\n    #    never fires. A real mouse event at the button's coordinates is the\n    #    only input those dialogs reliably honour, exactly as the browser\n    #    layer already refuses synthetic `element.click()` for real input.\n    if not right and not double and not real:\n        role = (entry.role or \"\").lower()\n        if BACKGROUND_ONLY.get() and role == 'button':\n            from .background_controls import invoke_button\n            if invoke_button(ctl):\n                _overlay_pulse()\n                return _result(EffectState.UNKNOWN, verified=False, method='native-button',\n                               via='win32-message', target=entry.describe())\n        if BACKGROUND_ONLY.get():\n            from .uia import quiet_control\n            ctl = quiet_control(ctl)\n        order: tuple[str, ...]\n        if role in (\"listitem\", \"treeitem\", \"option\", \"tab\", \"dataitem\",\n                    \"griditem\", \"menuitemradio\"):\n            order = (\"select\", \"invoke\", \"toggle\")\n        elif role in (\"checkbox\", \"radio\", \"switch\", \"menuitemcheckbox\"):\n            order = (\"toggle\", \"invoke\", \"select\")\n        else:\n            order = (\"invoke\", \"toggle\", \"select\")\n        limit = None\n        if role == \"listitem\":\n            # Measured quiet limit (quiet_limits.py): Office start-screen tiles\n            # acknowledge Select without opening, while Invoke opens them.\n            from .quiet_limits import ancestor_ids, limit_for\n            limit = limit_for(\"click\", entry.process, role, ancestor_ids(ctl))\n            if limit is not None and limit.effect == \"prefer_invoke\":\n                order = (\"invoke\", \"select\", \"toggle\")\n\n        patterns = {\n            \"invoke\": (lambda: ctl.GetInvokePattern(), lambda p: p.Invoke()),\n            \"toggle\": (lambda: ctl.GetTogglePattern(), lambda p: p.Toggle()),\n            \"select\": (lambda: ctl.GetSelectionItemPattern(), lambda p: p.Select()),\n        }\n        if role in (\"combobox\", \"button\"):\n            # Dropdown buttons can expose ExpandCollapse without Invoke;\n            # perception already reports their collapsed/expanded state.\n            # Try this only when the primary action patterns are absent.\n            order = (*order, \"expand\")\n            patterns[\"expand\"] = (lambda: ctl.GetExpandCollapsePattern(),\n                                  _expand_if_collapsed)\n        for name in order:\n            getter, action = patterns[name]\n            pat = _safe(getter, None)\n            if pat is None:\n                continue\n            if name == \"expand\" and _safe(lambda: int(pat.ExpandCollapseState), -1) == 1:\n                continue  # A known no-op may choose another route before dispatch.\n            before = _safe(lambda: int(pat.ToggleState), None) if name == \"toggle\" else None\n            was_selected = _safe(lambda: bool(pat.IsSelected), None) if name == \"select\" else None\n            try:\n                action(pat)\n            except Exception as exc:\n                # The provider can act before losing its reply. Trying another\n                # pattern or a physical click here would duplicate that effect.\n                raise ProtocolError(ErrorCode.INTERNAL, f\"{name} result is unknown\",\n                                    hint=\"Observe before choosing another action.\",\n                                    effect_state=EffectState.UNKNOWN) from exc\n            extra = {\"quiet_limit\": limit.id} if limit is not None else {}\n            if was_selected:\n                # Selecting an already selected item changes nothing; reporting\n                # it as committed hid a tile that never opened (2026-10-05).\n                _overlay_pulse(verified=False)\n                return _result(EffectState.UNKNOWN, verified=False, method=name,\n                               via=\"uia-pattern\", target=entry.describe(), no_change=True,\n                               note=\"the item was already selected, so selecting it changed \"\n                                    \"nothing; to open it, use --double or press Enter on it\",\n                               **extra)\n            verified = _semantic_state(pat, name, before)\n            _overlay_pulse(verified=verified)\n            return _result(EffectState.COMMITTED if verified else EffectState.UNKNOWN,\n                           verified=verified, method=name,\n                           via=\"uia-pattern\", target=entry.describe(), **extra)\n\n    # 1b. Posted-message rung (quiet, 2026-10-08): an addressed click to the\n    #    deepest child window at the element's centre - the OS pointer never\n    #    moves and the target never activates. The family table declines the\n    #    surfaces that silently drop posted input (measured per window class,\n    #    quiet_limits.FAMILY_RULES). An elevated target is still posted -\n    #    never refused - and the result says so (owner decision, handoff\n    #    section 3 item 7). A click carries no value postcondition, so\n    #    like every other click route the verdict stays UNKNOWN: observe\n    #    before relying on it.\n    if BACKGROUND_ONLY.get() and not right and not double and not real:\n        refusal = _posted_click_refusal(entry)\n        if refusal is not None:\n            raise InteractiveRequired(f\"Posted click declined: {refusal[1]}\",\n                                      code=refusal[0])\n        posted_hwnd = _posted_target_hwnd(entry)\n        rect = _safe(lambda: ctl.BoundingRectangle, None)\n        if posted_hwnd and rect is not None and rect.right > rect.left:\n            px, py = ((rect.left + rect.right) // 2,\n                      (rect.top + rect.bottom) // 2)\n            _require_on_screen(px, py, entry)\n            from . import background_controls as _bc\n            elevated = _bc.integrity_allows(posted_hwnd) is False\n            landed = _bc.post_click(posted_hwnd, px, py)\n            _overlay_pulse(verified=False)\n            return _result(EffectState.UNKNOWN, verified=False,\n                           method=\"posted-click\", via=\"posted-mouse\",\n                           target=entry.describe(),\n                           sent_to_class=_bc.class_name(landed),\n                           **({\"note\": _INTEGRITY_NOTE}\n                              if elevated else {}))\n\n    # 2. Coordinate fallback. Scroll into view first so the click cannot land\n    #    on a different element that occupies the stale rectangle.\n    require_interactive(\"Coordinate click fallback\")\n    if not BACKGROUND_ONLY.get():\n        # Real input goes to whatever window is physically on top at these\n        # coordinates; if ours is buried, the click hits the wrong app (S88).\n        # The screen is handed back afterwards - see foreground_returned.\n        handle = _owning_window(entry)\n        window = find_window(f\"#{handle}\") if handle else None\n        if window is None:\n            raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND, \"Click target window is unavailable\")\n        _raise_and_verify(window, f\"#{handle}\")\n    _safe(lambda: ctl.ScrollIntoView())\n    rect = _safe(lambda: ctl.BoundingRectangle, None)\n    if rect is None or rect.right <= rect.left:\n        raise ProtocolError(\n            ErrorCode.TARGET_NOT_VISIBLE,\n            f\"{entry.describe()} has no clickable area\",\n            hint=\"It may be scrolled out of view or hidden.\")\n    x, y = (rect.left + rect.right) // 2, (rect.top + rect.bottom) // 2\n    _require_on_screen(x, y, entry)\n    _overlay_aim(x, y)          # re-aim at the fresh, scrolled-into-view point\n    try:\n        if right:\n            ctl.RightClick(waitTime=0.05)\n        elif double:\n            ctl.DoubleClick(waitTime=0.05)\n        else:\n            ctl.Click(waitTime=0.05)\n    except Exception as exc:\n        # The mouse event was dispatched or not — we cannot tell. Never claim\n        # nothing happened.\n        raise ProtocolError(\n            ErrorCode.INTERNAL, f\"click failed: {exc}\",\n            hint=\"Inspect the current state before retrying.\",\n            effect_state=EffectState.UNKNOWN) from exc\n    _overlay_pulse()\n    return _result(EffectState.UNKNOWN, verified=False, method=\"coordinate\",\n                   via=\"physical\", at=[x, y], target=entry.describe())\n\n\ndef _semantic_state(pattern: Any, method: str, before: int | None) -> bool:\n    \"\"\"Bounded local readback; generic Invoke has no universal postcondition.\"\"\"\n    if method not in (\"toggle\", \"select\", \"expand\"):\n        return False\n    deadline, stable = time.monotonic() + 0.5, 0\n    while time.monotonic() < deadline:\n        if method == \"toggle\":\n            after = _safe(lambda: int(pattern.ToggleState), None)\n            matched = before is not None and after is not None and after != before\n        elif method == \"select\":\n            matched = _safe(lambda: bool(pattern.IsSelected), False)\n        else:\n            matched = _safe(lambda: int(pattern.ExpandCollapseState), -1) == 1\n        stable = stable + 1 if matched else 0\n        if stable >= 2:\n            return True\n        time.sleep(0.025)\n    return False\n\n\n# --- text --------------------------------------------------------------------\n\ndef set_value(store: RefStore, ref: str, value: str, delivery_mode: str | None = None) -> dict[str, Any]:\n    \"\"\"Replace a field's contents via the value pattern, then verify.\"\"\"\n    entry = store.resolve(ref)\n    _guard(entry)\n    if entry.element_token:\n        _overlay_aim_rect(entry)\n        res = _driver_action(entry, \"set_value\",\n                             {\"pid\": entry.window_pid, \"value\": value},\n                             verb=\"set_value\",\n                             first=_requested_first(delivery_mode, \"background\", \"Foreground set-value\"))\n        if res is not None:\n            # CUA's verdict as it is: committed only with CUA's own evidence\n            # (K2c); fx10: no window read follows, as CUA's set_value makes\n            # none (impl_.rs:6188-6189).\n            _overlay_pulse(verified=res.get(\"effect_state\") == EffectState.COMMITTED.value)\n            return res\n    vp = _value_pattern(entry)\n    if vp is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"{entry.describe()} does not expose a settable value\",\n            hint=\"Use `auto type` to send keystrokes instead.\")\n    _overlay_aim_ref(entry)\n    result: dict[str, Any] = {}\n    try:\n        result = _set_value_body(entry, vp, value)\n        if type(vp).__name__ == 'NativeEditValue':\n            result.update(via='win32-message', method='native-edit')\n        return result\n    finally:\n        _overlay_pulse(verified=result.get(\"verified\") is True)\n\n\ndef _set_value_body(entry: ElementRef, vp: Any, value: str) -> dict[str, Any]:\n    from .quiet_limits import surface_rule_for, value_shapes_of\n    process = getattr(entry, \"process\", \"\") or \"\"\n    if not process:\n        # RC-001 run-2: refs resolved from some harness paths carry no\n        # process; the surface rules are process-gated and would silently\n        # not fire. Resolve from the owning window's pid.\n        hwnd = _owning_window(entry) or _posted_target_hwnd(entry)\n        pid = 0\n        if hwnd:\n            import ctypes\n            from ctypes import wintypes\n            pidval = wintypes.DWORD()\n            ctypes.windll.user32.GetWindowThreadProcessId(\n                wintypes.HWND(hwnd), ctypes.byref(pidval))\n            pid = pidval.value\n        if pid:\n            try:\n                import psutil as _psutil\n                process = (_psutil.Process(pid).name() or \"\").lower()\n            except Exception:\n                process = \"\"\n    rule = surface_rule_for(\"set_value\", process, value)\n    # RC-001 (triple-proven 2026-10-09): ValuePattern writes on fresh Excel\n    # grid DataItems ack-without-write and the provider echoes every later\n    # same-channel read. The posted-grid route (select -> posted chars ->\n    # posted Enter) is measured (cua-dash ~30x) and verified live for\n    # formulas - it is now the PRIMARY for every grid DataItem write,\n    # with the fresh read-back judging the result.\n    if BACKGROUND_ONLY.get() and (entry.role or \"\").lower() in (\"dataitem\", \"griditem\", \"cell\"):\n        try:\n            posted = _posted_grid_entry(entry, value)\n        except Exception:\n            posted = False\n        if posted:\n            elevated = posted == \"posted-elevated\"\n            after = None\n            deadline = time.monotonic() + 2.5\n            while time.monotonic() < deadline:\n                after = _safe(lambda: vp.Value, None)\n                if after is not None and after != value:\n                    return _result(EffectState.COMMITTED,\n                                   target=entry.describe(), requested=value,\n                                   actual=after, method=\"posted-grid\",\n                                   via=\"posted-text\",\n                                   **({\"note\": _INTEGRITY_NOTE}\n                                      if elevated else {}))\n                time.sleep(0.25)\n            if after == value:\n                note = (\"the cell holds the input as literal \"\n                        \"text; it was not parsed\")\n                if elevated:\n                    note = f\"{note}; {_INTEGRITY_NOTE}\"\n                return _result(EffectState.UNKNOWN, target=entry.describe(),\n                               actual=after, method=\"posted-grid\",\n                               via=\"posted-text\", verified=False,\n                               note=note)\n            # unreadable: fall through to the rule/editor paths below\n    if rule is not None and rule.effect == \"editor_required\":\n        # Measured (quiet_limits.py SURFACE_RULES): this surface stores\n        # value-pattern writes as literal text — the pattern bypasses the\n        # field's parser while the read-back still matches, so it would read\n        # as verified. The field editor has to see the entry: decline quietly\n        # so the DR-02 fallback can run the click + entry + commit path.\n        # Zero-cursor rung FIRST (stage 2, measured in the cua-dash session):\n        # select the cell quietly, post the formula characters and a posted\n        # Enter, then judge from the read-back. The interactive refusal fires\n        # only if this measured route is unavailable (run 5 lesson: the\n        # refusal used to precede the rung, making it dead code in quiet mode).\n        posted = False\n        if BACKGROUND_ONLY.get():\n            try:\n                posted = _posted_grid_entry(entry, value)\n            except Exception:\n                posted = False\n            if not posted:\n                require_interactive(\n                    f\"Value entry on {rule.id} needs the field editor \"\n                    \"(posted route unavailable)\",\n                    code=\"background_known_limit\")\n        if posted:\n            # Excel keeps the cell in edit mode briefly after the posted\n            # Enter: the cached Value pattern can return None until the\n            # grid republishes. Poll a fresh read (2.5s) before judging —\n            # an immediate None once caused a needless physical fallback.\n            elevated = posted == \"posted-elevated\"\n            after = None\n            deadline = time.monotonic() + 2.5\n            while time.monotonic() < deadline:\n                after = _safe(lambda: vp.Value, None)\n                if after is not None and after != value:\n                    return _result(EffectState.COMMITTED,\n                                   target=entry.describe(), requested=value,\n                                   actual=after, method=\"posted-grid\",\n                                   via=\"posted-text\",\n                                   **({\"note\": _INTEGRITY_NOTE}\n                                      if elevated else {}))\n                time.sleep(0.25)\n            if after == value:\n                note = (\"the cell reads back the formula as \"\n                        \"literal text; it was not computed\")\n                if elevated:\n                    note = f\"{note}; {_INTEGRITY_NOTE}\"\n                return _result(EffectState.UNKNOWN, target=entry.describe(),\n                               actual=after, method=\"posted-grid\",\n                               via=\"posted-text\", verified=False,\n                               note=note)\n            # unreadable throughout: fall through to the interactive editor\n        if _real_replace_value(entry, value,\n                               typed=\"rtl\" in value_shapes_of(value),\n                               edit_mode=True):\n            after = _safe(lambda: vp.Value, None)\n            if after == value:\n                if value.startswith(\"=\"):\n                    # The cell reads back exactly what was sent: the parser\n                    # never saw it. This is the ValuePattern literal-text\n                    # failure in a different coat - report UNKNOWN, never\n                    # a verified success.\n                    return _result(EffectState.UNKNOWN,\n                                   target=entry.describe(), actual=after,\n                                   method=\"editor\", via=\"physical\",\n                                   verified=False,\n                                   note=\"the cell reads back the formula as \"\n                                        \"literal text; it was not computed\")\n                return _result(EffectState.COMMITTED, target=entry.describe(),\n                               actual=after, method=\"editor\", via=\"physical\",\n                               verified=True,\n                               note=f\"{rule.id}: entered through the field editor\")\n            if after is not None:\n                return _result(EffectState.COMMITTED, target=entry.describe(),\n                               requested=value, actual=after, mismatch=True,\n                               method=\"editor\", via=\"physical\")\n        # Editor path did not land; fall through to the normal patterns so the\n        # result stays an honest observation rather than a silent refusal.\n    before = _safe(lambda: vp.Value, None)\n    try:\n        vp.SetValue(value)\n    except Exception as exc:\n        raise ProtocolError(ErrorCode.INTERNAL, f\"set value failed: {exc}\",\n                            effect_state=EffectState.UNKNOWN) from exc\n\n    actual = _safe(lambda: vp.Value, None)\n    if actual is None:\n        return _result(EffectState.UNKNOWN, target=entry.describe(),\n                       via=\"uia-pattern\", verified=False,\n                       note=\"this field does not expose its value; \"\n                            \"observe to confirm the result\")\n    if actual == value:\n        if value.startswith(\"=\"):\n            # RC-001 run-2: a formula echoed back verbatim means it was\n            # stored as literal text - the parser never saw it. Never a\n            # success, even though the fresh walk agrees.\n            if not BACKGROUND_ONLY.get() and \\\n                    (entry.role or \"\").lower() == \"dataitem\":\n                if _real_replace_value(entry, value, edit_mode=True):\n                    after2 = _safe(lambda: vp.Value, None)\n                    if after2 is not None and after2 != value:\n                        return _result(EffectState.COMMITTED,\n                                       target=entry.describe(),\n                                       requested=value, actual=after2,\n                                       method=\"editor\", via=\"physical\")\n                return _result(EffectState.UNKNOWN, target=entry.describe(),\n                               actual=actual, via=\"uia-pattern\",\n                               verified=False,\n                               note=\"the cell holds the formula as literal \"\n                                    \"text; the escalated editor could not \"\n                                    \"be verified either\")\n        if (entry.role or \"\").lower() == \"dataitem\":\n            # RC-001: grid providers ECHO quiet writes — the read-back\n            # matches while the visible grid stays empty. Trust only a\n            # fresh walk; on echo, escalate to the proven editor route.\n            fresh = _fresh_grid_value(entry)\n            if fresh is None or fresh != actual:\n                if BACKGROUND_ONLY.get():\n                    raise InteractiveRequired(\n                        f\"{entry.describe()} echoed the quiet write without \"\n                        \"applying it (fresh observation disagrees)\",\n                        code=\"background_value_ignored\")\n                if _real_replace_value(entry, value, edit_mode=True):\n                    after2 = _safe(lambda: vp.Value, None)\n                    if after2 is not None and after2 != value:\n                        return _result(EffectState.COMMITTED,\n                                       target=entry.describe(),\n                                       requested=value, actual=after2,\n                                       method=\"editor\", via=\"physical\")\n                return _result(EffectState.UNKNOWN, target=entry.describe(),\n                               actual=actual, via=\"uia-pattern\",\n                               verified=False,\n                               note=\"the grid echoed the write without \"\n                                    \"applying it; escalated editor could \"\n                                    \"not be verified either\")\n        return _result(EffectState.COMMITTED, target=entry.describe(),\n                       actual=actual, via=\"uia-pattern\", verified=True)\n    if actual != before:\n        # Not an error: many fields reformat input (dates, phone numbers).\n        # Report the difference and let the caller judge.\n        return _result(EffectState.COMMITTED, target=entry.describe(),\n                       requested=value, actual=actual, mismatch=True,\n                       via=\"uia-pattern\")\n\n    # `actual == before`: the set was acked and changed nothing. Windows 11\n    # common-file dialogs do exactly this — the rename/filename field smiles\n    # at SetValue and keeps the old name (ledger R27) — and the only input\n    # they honour is real: a real mouse click into the field, select-all,\n    # clipboard paste. Try that once, then verify like everything else.\n    if BACKGROUND_ONLY.get():\n        # Read-back equals the value before the call: the quiet SetValue\n        # changed nothing, so no input took effect and the one-time\n        # interactive fallback may use real input (was a plain UNKNOWN error,\n        # which disabled the fallback; measured on Excel's Create Table range).\n        raise InteractiveRequired(f\"{entry.describe()} ignored the background value pattern\",\n                                  hint=\"Use the application's API or an isolated interactive session.\",\n                                  code=\"background_value_ignored\")\n    if before != value and _real_replace_value(entry, value):\n        after = _safe(lambda: vp.Value, None)\n        if after == value:\n            return _result(EffectState.COMMITTED, target=entry.describe(),\n                           actual=after, method=\"real_paste\", via=\"physical\",\n                           note=\"value pattern was ignored; real input used\")\n        if after is not None and after != before:\n            return _result(EffectState.COMMITTED, target=entry.describe(),\n                           requested=value, actual=after, mismatch=True,\n                           method=\"real_paste\", via=\"physical\")\n    raise ProtocolError(\n        ErrorCode.UNSUPPORTED,\n        f\"{entry.describe()} ignored both the value pattern and real input\",\n        hint=\"The field may be read-only or covered by another window. \"\n             \"Observe the window, or ask the user via `auto request-help`.\",\n        # Real input was injected with no visible effect: claiming NOTHING\n        # happened would be a guess.\n        effect_state=EffectState.UNKNOWN)\n\n\ndef _fresh_grid_value(entry: ElementRef) -> \"str | None\":\n    \"\"\"Fresh-observation read for grid cells (RC-001, 2026-10-09): the\n    cached element's provider ECHOES ack-without-write on fresh workbook\n    grids (read-back matches while the visible grid stays empty), so the\n    truth only comes from a NEW walk from the top window. Returns the\n    cell's visible value, or None when it cannot be seen.\"\"\"\n    import uiautomation as ua\n    handle = _owning_window(entry) or getattr(entry, \"top_window\", 0) or 0\n    if not handle:\n        return None\n    name = _safe(lambda: str(entry.control.Name), \"\") or \"\"\n    if not name:\n        return None\n\n    def _walk(ctrl, depth):\n        if depth > 12:\n            return None\n        for child in _safe(lambda: ctrl.GetChildren(), []) or []:\n            cname = _safe(lambda: str(child.Name), \"\")\n            crole = _safe(lambda: str(child.ControlTypeName), \"\")\n            if cname == name and crole in (\"DataItemControl\", \"ListItemControl\"):\n                return _safe(lambda: child.GetValuePattern().Value, None)\n            deeper = _walk(child, depth + 1)\n            if deeper is not None:\n                return deeper\n        return None\n\n    try:\n        root = ua.ControlFromHandle(int(handle))\n    except Exception:\n        return None\n    if root is None:\n        return None\n    return _walk(root, 0)\n\n\ndef _value_pattern(entry: ElementRef) -> Any:\n    control = entry.control\n    if BACKGROUND_ONLY.get():\n        from .background_controls import edit_value\n        native = edit_value(entry.control)\n        if native is not None:\n            return native\n        from .uia import quiet_control\n        control = quiet_control(control)\n    return _safe(lambda: control.GetValuePattern(), None)\n\n\n@contextmanager\ndef _saved_cursor():\n    \"\"\"Zero-net-displacement contract for physical rungs: the real pointer\n    returns to where the user left it, even when the action fails (the\n    cua-driver SendInput rung saves/restores around input; its foreground\n    branch forgets - the measured defect we do not copy, 2026-10-08).\"\"\"\n    import ctypes\n    from ctypes import wintypes\n    pt = wintypes.POINT()\n    have = bool(ctypes.windll.user32.GetCursorPos(ctypes.byref(pt)))\n    try:\n        yield\n    finally:\n        if have:\n            ctypes.windll.user32.SetCursorPos(int(pt.x), int(pt.y))\n\n\n_POSTED_GATE_TRACE = os.environ.get(\"AUTOSKILL_POSTED_GATE_TRACE\", \"\")\n\n\ndef _trace_gate(entry: ElementRef, msg: str) -> None:\n    \"\"\"RC-001 run-3 follow-up: the posted-grid rung refused silently; log\n    which gate while the fix is being proven (env-gated, removable).\"\"\"\n    if not _POSTED_GATE_TRACE:\n        return\n    try:\n        with open(_POSTED_GATE_TRACE, \"a\", encoding=\"utf-8\") as fh:\n            fh.write(time.strftime(\"%H:%M:%S\") + \" \" + entry.describe()\n                     + \": \" + msg + \"\\n\")\n    except Exception:\n        pass\n\n\ndef _posted_grid_entry(entry: ElementRef, value: str) -> str | bool:\n    \"\"\"Zero-cursor formula entry (stage 2, measured): quiet-select the cell\n    (UIA Invoke, then SelectionItem — the cua-dash session's exact chain),\n    post the formula as WM_CHAR to the focused descendant, commit with a\n    posted VK_RETURN. Measured working ~30x (DataItem select -> posted\n    COUNTIF -> posted Enter -> computed value, e.g. H12=\"166\"); Excel\n    classes are unlisted in the family table, so posting proceeds under\n    the persistence read-back. Returns False when the route is\n    unavailable, otherwise the tag \"posted\" or \"posted-elevated\" (the\n    advisory integrity read said the target outranks us; the post still\n    went out - owner decision, handoff section 3 item 7). The caller\n    judges computed-vs-literal from a fresh read.\"\"\"\n    from . import background_controls as _bc\n    from .quiet_limits import posted_drop_reason as _pdr\n    ctl = entry.control\n    invoke = _safe(lambda: ctl.GetInvokePattern(), None)\n    if invoke is not None:\n        invoke.Invoke()\n    else:\n        sel = _safe(lambda: ctl.GetSelectionItemPattern(), None)\n        if sel is None:\n            return False\n        sel.Select()\n    time.sleep(0.3)\n    hwnd = _owning_window(entry)\n    if not hwnd:\n        _trace_gate(entry, \"no hwnd from owning-window walk\")\n        # Excel grid DataItems are windowless and the ref may carry no\n        # top_window (CM-47 gap on this path): walk up to the first\n        # ancestor with a real handle (Excel: the XLMAIN frame).\n        node = ctl\n        for _ in range(12):\n            node = _safe(lambda: node.GetParentControl(), None)\n            if node is None:\n                break\n            h = _safe(lambda: int(getattr(node, \"NativeWindowHandle\", 0) or 0), 0)\n            if h:\n                hwnd = h\n                break\n    if not hwnd:\n        _trace_gate(entry, \"no hwnd after ancestor walk\")\n        return False\n    # Owner decision (handoff section 3 item 7): an elevated target is never\n    # refused - the post is attempted and the read-back judges it (the read\n    # flaps on Excel anyway: measured run 8, the same B4 hwnd read False then\n    # posted fine). The integrity read below is advisory only: it tags the\n    # returned tag so the caller can tell the user Windows may drop it.\n    elevated = _bc.integrity_allows(hwnd) is False\n    drop = None\n    from .quiet_limits import posted_drop_reason as _pdr\n    drop = _pdr(_bc.class_name(hwnd), \"text\")\n    if drop is not None:\n        _trace_gate(entry, f\"class-drop {drop[0]}\")\n        return False\n    _trace_gate(entry, f\"posting via {_bc.class_name(hwnd)}\")\n    _bc.post_text(hwnd, value)\n    time.sleep(0.15)\n    _bc.post_key(hwnd, _bc.VK_RETURN)\n    time.sleep(0.4)\n    return \"posted-elevated\" if elevated else \"posted\"\n\n\ndef _real_replace_value(entry: ElementRef, value: str, *, typed: bool = False,\n                        edit_mode: bool = False) -> bool:\n    \"\"\"Real-input replacement for fields that ignore the value pattern:\n    a real mouse click (not a UIA focus call), select-all, then paste —\n    or, with `typed`, per-character entry for values the clipboard pipeline\n    corrupts (measured: RTL script mixed into formulas, 2026-10-06).\n\n    `edit_mode` is for grid cells (Excel): a bare click only SELECTS the\n    cell, and Ctrl+A would select the whole sheet. F2 opens the cell\n    editor first, so select-all targets the cell's own text.\n\n    Needs the foreground, and gives it straight back.\n    \"\"\"\n    with foreground_returned():\n        return _real_replace_value_inner(entry, value, typed=typed,\n                                         edit_mode=edit_mode)\n\n\ndef _real_replace_value_inner(entry: ElementRef, value: str, *, typed: bool = False,\n                              edit_mode: bool = False) -> bool:\n    require_interactive(\"Physical text replacement\")\n    ua = _require_uia()\n    ctl = entry.control\n    hwnd = _owning_window(entry)\n    if hwnd:\n        # The foreground is a verified transaction: force it, confirm the\n        # exact window actually took it, and send nothing otherwise - a\n        # failed swap must never land input on whichever window kept focus\n        # (cua-driver's with_confirmed_foreground, 2026-10-08 audit).\n        _force_foreground(hwnd)\n        deadline = time.monotonic() + 0.6\n        while _foreground_handle() != hwnd and time.monotonic() < deadline:\n            time.sleep(0.05)\n        if _foreground_handle() != hwnd:\n            raise ProtocolError(\n                ErrorCode.INTERNAL, \"the window did not take the foreground\",\n                hint=\"no input was sent; the window may be blocked by the \"\n                     \"system foreground lock\",\n                effect_state=EffectState.NONE)\n    _safe(lambda: ctl.ScrollIntoView())\n    rect = _safe(lambda: ctl.BoundingRectangle, None)\n    if rect is None or rect.right <= rect.left:\n        return False\n    x, y = (rect.left + rect.right) // 2, (rect.top + rect.bottom) // 2\n    _require_on_screen(x, y, entry)\n    _overlay_aim(x, y)\n    try:\n        with _saved_cursor():\n            ctl.Click(waitTime=0.05)          # real mouse event — the whole point\n            time.sleep(0.1)\n            if edit_mode:\n                # Grid cells (Excel): a paste into the SELECTED cell commits and\n                # parses natively; F2 edit mode + Ctrl+A instead leaves the cell\n                # open, and Excel then interrupts with an autocorrect prompt\n                # (measured twice live, 2026-10-07). Typing over a selected cell\n                # replaces its content the same way.\n                if typed:\n                    ua.SendKeys(_escape_sendkeys(value), interval=TYPE_INTERVAL,\n                                waitTime=0)\n                    time.sleep(0.05)\n                    ua.SendKeys(\"{Enter}\", waitTime=0)   # commit the typed entry\n                    return True\n                return _paste(ua, value)\n            ua.SendKeys(\"{Ctrl}a\", waitTime=0)\n            time.sleep(0.05)\n            if typed:\n                ua.SendKeys(_escape_sendkeys(value), interval=TYPE_INTERVAL, waitTime=0)\n                return True\n            return _paste(ua, value)\n    except Exception:\n        return False\n\n\nTYPE_INTERVAL = 0.02\n\n# RC-012 fix (2026-10-09): the window the session's last open-app produced.\n# Unaimed keyboard/text input refuses to deliver anywhere else — the\n# notepad parity leg measured 23 chars delivered into the orchestrator's\n# own window while the intended app lacked focus.\n_session_target: int = 0\n\n\ndef _session_target_check() -> None:\n    \"\"\"Refuse unaimed input when the session's launched window is not the\n    foreground one (the notepad leg measured text delivered into an\n    unrelated window while reporting the target honestly).\"\"\"\n    if _session_target and _foreground_handle() != _session_target:\n        raise InteractiveRequired(\n            \"the application this session launched is not in the foreground\",\n            hint=\"no input was sent; focus it, or pass --window to aim \"\n                 \"explicitly\",\n            code=\"background_window_not_focused\")\n\n\ndef type_text(store: RefStore, text: str, *, ref: str | None = None,\n              method: str = \"auto\", interval: float = TYPE_INTERVAL, window: str | None = None,\n              delay_ms: int | None = None, x: float | None = None,\n              y: float | None = None, delivery_mode: str | None = None) -> dict[str, Any]:\n    with foreground_returned():\n        if x is not None or y is not None:\n            _point_target(x, y, ref, window)\n            return _driver_type_point(text, window or \"\", x, y, delay_ms, delivery_mode)\n        from . import driver_backend\n        if window and not ref and method == \"auto\" and driver_backend.supports(\"type_text\"):\n            # p3r D2 (G-W04): CUA's type_text on pid + window_id alone (impl_.rs:4728-4800), never the Python keyboard.\n            return _driver_type_point(text, window, None, None, delay_ms, delivery_mode)\n        return _type_text(store, text, ref=ref, method=method,\n                          interval=interval, window=window,\n                          delay_ms=delay_ms, delivery_mode=delivery_mode)\n\n\ndef _driver_type_point(text: str, window: str, x: Any, y: Any,\n                       delay_ms: int | None, delivery_mode: str | None = None) -> dict[str, Any]:\n    \"\"\"p3h: CUA type_text at a window point (the PX cells, cross_platform_behavior_test.rs:752-808): CUA resolves\n    and focuses the element under the point itself. Driver only - the Python keyboard path cannot aim at a point.\n    p3r D2: x/y None = CUA's untargeted type_text on pid + window_id (the window's focused element).\"\"\"\n    from types import SimpleNamespace\n\n    from . import driver_backend\n    w = _driver_window(window) if driver_backend.supports(\"type_text\") else None\n    hwnd = int(_safe(lambda: w.NativeWindowHandle, 0) or 0) if w else 0\n    pid = int(_safe(lambda: w.ProcessId, 0) or 0) if w else 0\n    refused = ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"typing on a window needs the driver's type_text and a window; \"\n                            \"nothing was sent\", effect_state=EffectState.NONE)\n    if not hwnd or not pid:\n        raise refused\n    point = {} if x is None else {\"x\": x, \"y\": y}\n    target = f\"window {(_safe(lambda: w.Name, '') or window)!r}\" + (f\" at ({x},{y})\" if point else \"\")\n    params = {\"text\": text, **({\"delay_ms\": delay_ms} if delay_ms is not None else {})}\n    entry = SimpleNamespace(ref=target, control=None, element_token=\"\",\n                            window_pid=pid, top_window=hwnd, rect=None,\n                            describe=lambda: target)\n    first = \"background\"\n    if not BACKGROUND_ONLY.get():\n        require_interactive(\"Typing at a point\" if point else \"Typing on a window\")\n        first = \"foreground\"\n    first = _requested_first(delivery_mode, first, \"Foreground typing\")\n    res = _driver_action(entry, \"type_text\", params, verb=\"type_text\",\n                         pixel_params=lambda: {\"pid\": pid, \"window_id\": hwnd, **point, **params},\n                         first=first)\n    if res is None:\n        raise refused\n    res.update(sent_to=target, chars=len(text))\n    return res\n\n\ndef _type_text(store: RefStore, text: str, *, ref: str | None = None,\n               method: str = \"auto\", interval: float = TYPE_INTERVAL,\n               window: str | None = None,\n               delay_ms: int | None = None, delivery_mode: str | None = None) -> dict[str, Any]:\n    \"\"\"Enter text, choosing the most reliable mechanism available.\n\n    Synthetic keystrokes are the *worst* way to enter text and the obvious one,\n    which is a bad combination. Measured on Notepad with a 59-character string:\n\n        interval=0.000   0/5 exact\n        interval=0.005   0/5 exact\n        interval=0.010   0/5 exact\n        interval=0.020   3/5 exact\n\n    The input queue drops and reorders characters under load, and the result is\n    *silently wrong text* — the single most dangerous failure this tool can\n    have, because nothing raises. So keystrokes are the last resort, not the\n    default, and every mechanism is verified by reading the field back.\n\n    Order: value pattern (atomic) -> clipboard paste (atomic, real input event)\n    -> keystrokes (real key events, unreliable for long text).\n\n    delay_ms (B8) is CUA type_text.delay_ms verbatim on the driver route\n    (impl_.rs:4613/:4731; CUA's 0..200/default-30 is CUA's own semantic,\n    never re-derived here): absent -> absent on the wire, given -> given.\n    On the Python keys rung it converts ms -> seconds for SendKeys; the\n    value and clipboard rungs ignore it exactly as CUA's atomic UIA rung\n    does (\"Ignored on the UIA path (SetValue is atomic)\", impl_.rs:4602).\n    \"\"\"\n    ua = _require_uia()\n    if not ref and not window:\n        _session_target_check()          # RC-012: never type into a bystander\n    entry = None\n    target = None\n    if not ref:\n        # No element target: the keys go to whatever has focus. Aim it, or at\n        # least name it in the result.\n        target = _aim_keyboard(window)\n    if ref:\n        entry = store.resolve(ref)\n        _guard(entry)\n        if entry.element_token:\n            _overlay_aim_rect(entry)\n            res = _driver_action(\n                entry, \"type_text\",\n                {\"text\": text,\n                 # B8: verbatim CUA param; absent stays absent so CUA\n                 # applies its own default 30 (the DR-02 re-issue merges\n                 # this same dict, so the pacing rides both deliveries).\n                 **({\"delay_ms\": delay_ms} if delay_ms is not None else {})},\n                verb=\"type_text\",\n                first=_requested_first(delivery_mode, \"background\", \"Foreground typing\"))\n            if res is not None:\n                # CUA's verdict as it is (K2c); fx10: no window read follows -\n                # CUA tells the caller to take a fresh snapshot instead\n                # (impl_.rs:5089-5109).\n                _overlay_pulse(verified=res.get(\"effect_state\") == EffectState.COMMITTED.value)\n                return res\n        if not BACKGROUND_ONLY.get():\n            _aim_keyboard(_window_selector(entry))\n            if not _safe(lambda: (entry.control.SetFocus(), True)[1], False):\n                raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                                    f\"could not focus {entry.describe()}\")\n        target = entry.describe()\n        time.sleep(0.05)\n        _overlay_aim_ref(entry)\n\n    vp = _value_pattern(entry) if entry else None\n    before = _safe(lambda: vp.Value, None) if vp is not None else None\n    if BACKGROUND_ONLY.get() and before is None:\n        raise InteractiveRequired(\"Quiet append needs a readable value to preserve existing text\",\n                                  code=\"background_value_unreadable\")\n\n    order = {\"auto\": [\"value\", \"clipboard\", \"keys\"],\n             \"value\": [\"value\"], \"clipboard\": [\"clipboard\"],\n             \"keys\": [\"keys\"]}.get(method)\n    if order is None:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, f\"unknown method {method!r}\",\n                            hint=\"Use auto, value, clipboard or keys.\")\n    if BACKGROUND_ONLY.get():\n        if method not in (\"auto\", \"value\"):\n            require_interactive(\"Clipboard or keyboard text entry\")\n        order = [\"value\"]\n    else:\n        # Measured surface rule (quiet_limits.py SURFACE_RULES): values that\n        # mix RTL script with ASCII are reordered by the clipboard pipeline\n        # into broken content; per-character entry preserves code points.\n        from .quiet_limits import surface_rule_for\n        srule = surface_rule_for(\n            \"type\", getattr(entry, \"process\", \"\") or \"\" if entry is not None else \"\", text)\n        if srule is not None and srule.effect == \"avoid_clipboard\" and \"clipboard\" in order:\n            order = [mech for mech in order if mech != \"clipboard\"]\n        # G-W04 (B19): a ref carrying a driver element_token is a\n        # driver-moved rung — after driver unavailability its Python\n        # fallback must not paste over the user's clipboard (auto becomes\n        # value -> keys, exactly the surface-rule filter shape above).\n        # Paste survives only as the explicit --method clipboard opt-in;\n        # pure Python refs (no token) keep the full order.\n        if (method == \"auto\" and \"clipboard\" in order\n                and getattr(entry, \"element_token\", None)):\n            order = [mech for mech in order if mech != \"clipboard\"]\n\n    used: str | None = None\n    for mech in order:\n        if mech == \"value\":\n            if vp is None or _safe(lambda: bool(vp.IsReadOnly), False):\n                continue\n            want = (before or \"\") + text\n            try:\n                vp.SetValue(want)\n            except Exception as exc:\n                raise ProtocolError(ErrorCode.INTERNAL, \"Text-entry result is unknown\",\n                                    hint=\"Read the field before any further input.\",\n                                    effect_state=EffectState.UNKNOWN) from exc\n            if text and before is not None:\n                # Some fields acknowledge SetValue and keep their old value\n                # (measured: Excel's Create Table range reverted to $A$1:$H$14\n                # while `type` reported \"committed\"). Unchanged read-back means\n                # nothing took effect: quiet delivery declines so the one-time\n                # interactive fallback can paste; interactive delivery moves on\n                # to the next mechanism.\n                time.sleep(0.15)\n                if _safe(lambda: vp.Value, None) == before:\n                    if BACKGROUND_ONLY.get():\n                        raise InteractiveRequired(\n                            f\"{target or 'the field'} ignored the background value pattern\",\n                            hint=\"No text was entered; interactive delivery can paste instead.\",\n                            code=\"background_value_ignored\")\n                    continue\n            used = \"value\"\n            break\n        elif mech == \"clipboard\":\n            if entry is None:\n                # No element to verify against, but the clipboard path is still\n                # the reliable one for long text in a focused window.\n                if _paste(ua, text):\n                    used = \"clipboard\"\n                    break\n                continue\n            if _paste(ua, text):\n                used = \"clipboard\"\n                break\n        else:\n            try:\n                # B8: the keys rung is the ONLY rung that paces - delay_ms\n                # converts ms -> seconds here (the honest Python analogue of\n                # CUA's per-character sleep, keyboard.rs:326); 0 is a real\n                # zero, absent keeps the private TYPE_INTERVAL default.\n                ua.SendKeys(_escape_sendkeys(text),\n                            interval=(delay_ms / 1000.0\n                                      if delay_ms is not None else interval),\n                            waitTime=0)\n                used = \"keys\"\n                break\n            except Exception as exc:\n                raise ProtocolError(\n                    ErrorCode.INTERNAL, f\"typing failed: {exc}\",\n                    effect_state=EffectState.UNKNOWN) from exc\n\n    if used is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED, \"no usable text-entry mechanism for this target\",\n            hint=\"Focus the field and try `--method keys`.\")\n\n    # Audit trail: the value pattern never touches the real keyboard or the\n    # user's clipboard; the other two mechanisms are physical input.\n    via = \"uia-pattern\" if used == \"value\" else \"physical\"\n    if type(vp).__name__ == 'NativeEditValue':\n        via = 'win32-message'\n\n    # Verification. Without it a dropped keystroke is indistinguishable from\n    # success, which is exactly how an agent reports a job well done on a form\n    # that now contains garbage.\n    time.sleep(0.15)\n    after = _safe(lambda: vp.Value, None) if vp is not None else None\n    if after is None:\n        _overlay_pulse()\n        return _result(EffectState.UNKNOWN, target=target, chars=len(text),\n                       method=used, via=via, verified=False,\n                       note=\"this control does not expose its value; \"\n                            \"observe to confirm the result\")\n    expected = (before or \"\") + text\n    if after != expected:\n        _overlay_pulse()\n        return _result(EffectState.COMMITTED, target=target, method=used,\n                       via=via, verified=False, mismatch=True,\n                       expected=expected[-120:], actual=after[-120:],\n                       note=\"the field does not contain what was sent. Read it \"\n                            \"before correcting; do not blindly retype.\")\n    _overlay_pulse(verified=True)\n    return _result(EffectState.COMMITTED, target=target, chars=len(text),\n                   method=used, via=via, verified=True)\n\n\ndef _paste(ua: Any, text: str) -> bool:\n    \"\"\"Clipboard paste, restoring whatever the user had. Their clipboard is\n    theirs; borrowing it silently and not giving it back is a real annoyance.\"\"\"\n    require_interactive(\"Clipboard paste\")\n    saved = _safe(lambda: ua.GetClipboardText(), None)\n    try:\n        if not _safe(lambda: (ua.SetClipboardText(text), True)[1], False):\n            return False\n        time.sleep(0.05)\n        ua.SendKeys(\"{Ctrl}v\", waitTime=0)\n        time.sleep(0.15)\n        return True\n    except Exception:\n        return False\n    finally:\n        if saved is not None:\n            _safe(lambda: ua.SetClipboardText(saved))\n\n\n_SENDKEYS_SPECIAL = \"{}()+^%\"\n\n\ndef _posted_target_hwnd(entry: ElementRef) -> int | None:\n    \"\"\"The window a posted delivery would address: the element's own HWND,\n    else its recorded top window (windowless elements, CM-47) - the\n    deepest-child walk lands the message on the right control either way.\"\"\"\n    handle = getattr(entry.control, \"NativeWindowHandle\", 0)\n    if isinstance(handle, int) and handle:\n        return handle\n    top = getattr(entry, \"top_window\", 0) or 0\n    return int(top) if top else None\n\n\ndef _posted_click_refusal(entry: ElementRef) -> tuple[str, str] | None:\n    \"\"\"(refusal code, reason) when a posted click must not be sent.\n\n    The family table names the window classes that silently drop posted\n    clicks while reporting success. Integrity is no longer consulted here:\n    an elevated target is posted anyway and the result carries the\n    advisory note (owner decision, handoff section 3 item 7).\n    \"\"\"\n    from .quiet_limits import posted_drop_reason\n    from . import background_controls as _bc\n    hwnd = _posted_target_hwnd(entry)\n    if not hwnd:\n        return (\"background_needs_physical_input\",\n                \"the element has no addressable window for posted delivery\")\n    drop = posted_drop_reason(_bc.class_name(hwnd), \"click\")\n    if drop is not None:\n        return (\"background_posted_dropped\", f\"{drop[0]}: {drop[1]}\")\n    return None\n\n\ndef _escape_sendkeys(text: str) -> str:\n    # Newlines are Enter key events, never literal characters: a literal\n    # 0x0A is dropped by rich editors and silently joins lines (measured in\n    # cua-driver, 2026-10-08 audit). A placeholder survives the per-character\n    # escaping and becomes {Enter} afterwards.\n    text = text.replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\").replace(\"\\n\", \"\\x00\")\n    escaped = \"\".join(\"{\" + c + \"}\" if c in _SENDKEYS_SPECIAL else c\n                      for c in text)\n    return escaped.replace(\"\\x00\", \"{Enter}\")\n\n\ndef _point_target(x: float | None, y: float | None, ref: str | None, window: str | None) -> None:\n    \"\"\"p3h: x/y aim CUA's PX target inside a named window (cross_platform_behavior_test.rs:752-808).\"\"\"\n    if (x is None) != (y is None) or ref or not window:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"x and y go together and need a window (not a ref); nothing was sent\",\n            effect_state=EffectState.NONE)\n\n\ndef press_key(store: RefStore, keys: str, *, ref: str | None = None,\n              window: str | None = None, x: float | None = None,\n              y: float | None = None, delivery_mode: str | None = None,\n              scope: str | None = None) -> dict[str, Any]:\n    with foreground_returned():\n        return _press_key(store, keys, ref=ref, window=window, x=x, y=y,\n                          delivery_mode=delivery_mode, scope=scope)\n\n\ndef _requested_first(delivery_mode: str | None, default: str, what: str) -> str:\n    \"\"\"p3r D6: CUA's delivery_mode on type_text / press_key / hotkey / set_value / scroll / drag (impl_.rs tool\n    schemas). Foreground passes the owner's interactive gate (as click's, p3h); absent keeps the verb's default.\"\"\"\n    if delivery_mode == \"foreground\":\n        if default != \"foreground\":\n            require_interactive(what)\n        return \"foreground\"\n    return \"background\" if delivery_mode == \"background\" else default\n\n\ndef _press_key(store: RefStore, keys: str, *, ref: str | None = None,\n               window: str | None = None, x: float | None = None,\n               y: float | None = None, delivery_mode: str | None = None,\n               scope: str | None = None) -> dict[str, Any]:\n    \"\"\"Send a key combination such as `Enter`, `Ctrl+S`, `Alt+F4`.\n\n    Pass `--ref` for a specific control, or `--window` to aim at an\n    application. With neither, the keys go wherever focus happens to be and the\n    result says so — read `sent_to` before trusting it.\n    \"\"\"\n    if x is not None or y is not None:\n        _point_target(x, y, ref, window)\n        driver = _driver_key(store, keys, ref=None, window=window, x=x, y=y, delivery_mode=delivery_mode)\n        if driver is None:\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                \"a key at a window point needs the driver's press_key/hotkey and a \"\n                                \"key name CUA knows; nothing was sent\",\n                                effect_state=EffectState.NONE)\n        return driver\n    if BACKGROUND_ONLY.get() and ref and keys.strip().lower() in (\"enter\", \"return\"):\n        entry = store.resolve(ref)\n        if not entry.element_token:      # b9: a driver ref takes CUA's press_key\n            return _activate_ref(entry, keys)\n    if not ref and not window and scope != \"desktop\":\n        _session_target_check()          # RC-012: never key into a bystander\n    if BACKGROUND_ONLY.get():\n        from .quiet_limits import limit_for\n        limit = limit_for(\"key\", _key_target_process(store, ref, window))\n        if limit is not None and limit.effect == \"interactive_required\":\n            raise InteractiveRequired(f\"Keyboard shortcut: {limit.reason}\",\n                                      hint=\"No key was sent; interactive delivery uses the real keyboard.\",\n                                      code=\"background_known_limit\")\n    driver = _driver_key(store, keys, ref=ref, window=window,\n                         delivery_mode=delivery_mode, scope=scope)\n    if driver is not None:\n        return driver\n    require_interactive(\"Keyboard shortcut\")\n    ua = _require_uia()\n    seq = _to_sendkeys(keys)\n    target = None\n    if ref:\n        entry = store.resolve(ref)\n        _guard(entry)\n        _aim_keyboard(_window_selector(entry))\n        if not _safe(lambda: (entry.control.SetFocus(), True)[1], False):\n            raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE, \"Cannot focus the key target\")\n        time.sleep(0.05)\n        target = entry.describe()\n    else:\n        target = _aim_keyboard(window)\n    before = _observable_state()\n    try:\n        ua.SendKeys(seq, waitTime=0)\n    except Exception as exc:\n        raise ProtocolError(ErrorCode.INTERNAL, f\"key press failed: {exc}\",\n                            effect_state=EffectState.UNKNOWN) from exc\n    changed = _observed_change(before)\n    if changed is None:\n        return _result(EffectState.UNKNOWN, keys=keys, sequence=seq, sent_to=target,\n                       verified=False, note=\"the keys were delivered; the result could not \"\n                                            \"be observed, so observe before relying on it\")\n    if not changed:\n        # Delivered but nothing observable changed. Measured 2026-10-05:\n        # Ctrl+N on Excel's start screen and Alt+F11 on a workbook reported\n        # \"committed\" while nothing happened. Some keys change nothing visible\n        # (Ctrl+S on a saved file), so this is \"unknown\", not a failure.\n        return _result(EffectState.UNKNOWN, keys=keys, sequence=seq, sent_to=target,\n                       verified=False, no_change=True,\n                       note=\"the keys were delivered but no window, title or focused \"\n                            \"element changed; observe before assuming they worked\")\n    return _result(EffectState.COMMITTED, keys=keys, sequence=seq,\n                   sent_to=target, observed_change=changed)\n\n\ndef _driver_key(store: RefStore, keys: str, *, ref: str | None,\n                window: str | None, x: float | None = None,\n                y: float | None = None, delivery_mode: str | None = None,\n                scope: str | None = None) -> dict[str, Any] | None:\n    \"\"\"B9: desktop.key on CUA's press_key / hotkey (impl_.rs:5291-5340,\n    :5625-5680). Quiet (background-only) mode: background first, the DR-02\n    foreground re-issue through _driver_action. Interactive mode: CUA's\n    foreground delivery directly (SendInput, impl_.rs:5953-5962) - the same\n    real-input meaning the Python path had there, and the only route on\n    which TranslateAccelerator/GetKeyState apps see a modifier (a posted\n    combo carries no system modifier state, impl_.rs:5906-5933). The result\n    stays CUA's unverifiable -> unknown, with no post-key observation, as in\n    CUA (b10r: the 0.8 s poll cost about 0.9 s per key). None keeps the\n    Python path: no target, a Python ref, a name CUA's table does not know,\n    or a driver that does not offer the method - nothing was sent.\"\"\"\n    call = _cua_key_call(keys)\n    if call is None or not (ref or window or scope == \"desktop\"):\n        return None\n    method, params = call\n    from . import driver_backend\n    if not driver_backend.supports(method):\n        return None\n    factory = None\n    if scope == \"desktop\" and not (ref or window):\n        from types import SimpleNamespace\n        target = \"desktop\"\n        entry = SimpleNamespace(ref=target, control=None, element_token=\"\",\n                                window_pid=0, top_window=0, rect=None,\n                                describe=lambda: target)\n\n        def factory() -> dict[str, Any]:\n            return {\"scope\": \"desktop\", **params}\n    elif ref:\n        entry = store.resolve(ref)\n        if not entry.element_token:\n            return None\n        _guard(entry)\n        target = entry.describe()\n    else:\n        w = _driver_window(window)\n        hwnd = int(_safe(lambda: w.NativeWindowHandle, 0) or 0) if w else 0\n        pid = int(_safe(lambda: w.ProcessId, 0) or 0) if w else 0\n        if not hwnd or not pid:\n            return None\n        target = f\"window {(_safe(lambda: w.Name, '') or window)!r}\"\n        from types import SimpleNamespace\n        entry = SimpleNamespace(ref=target, control=None, element_token=\"\",\n                                window_pid=pid, top_window=hwnd, rect=None,\n                                describe=lambda: target)\n        point = {\"x\": x, \"y\": y} if x is not None else {}\n\n        def factory() -> dict[str, Any]:\n            return {\"pid\": pid, \"window_id\": hwnd, **point, **params}\n    first = \"background\"\n    if not BACKGROUND_ONLY.get():\n        require_interactive(\"Keyboard shortcut\")\n        first = \"foreground\"\n    first = _requested_first(delivery_mode, first, \"Foreground key\")\n    # perf1: no pointer motion - CUA's PressKeyTool and HotkeyTool make no overlay call (impl_.rs:5291-6002).\n    res = _driver_action(entry, method, params, verb=\"key\", pixel_params=factory,\n                         first=first)\n    if res is None:\n        return None\n    res.update(keys=keys, sent_to=target)\n    return res\n\n\n# B9: the names CUA's key table knows (platform-windows input/keyboard.rs:\n# 858-910 at pin 815dfd96). Any other multi-letter name would be sent as its\n# FIRST character (:905-913), so it keeps the Python path and its message.\n_CUA_KEYS = frozenset({\n    \"enter\", \"return\", \"tab\", \"escape\", \"esc\", \"space\", \"backspace\", \"delete\",\n    \"del\", \"insert\", \"ins\", \"home\", \"end\", \"pageup\", \"pgup\", \"pagedown\", \"pgdn\",\n    \"up\", \"down\", \"left\", \"right\", \"capslock\", \"numlock\",\n    # fx4 (t1 I4): the modifier names the same table maps as keys (:902-905).\n    \"ctrl\", \"control\", \"shift\", \"alt\", \"win\", \"windows\", \"meta\", \"command\", \"cmd\",\n    *(f\"f{i}\" for i in range(1, 13))})\n\n\ndef _cua_key_call(keys: str) -> tuple[str, dict[str, Any]] | None:\n    \"\"\"('press_key', {key}) or ('hotkey', {keys: modifiers + [key]}) in CUA's\n    vocabulary, or None for anything CUA would not read as written.\"\"\"\n    parts = [p.strip().lower() for p in keys.replace(\"-\", \"+\").split(\"+\") if p.strip()]\n    if not parts:\n        return None\n    mods, key = parts[:-1], {\"back\": \"backspace\"}.get(parts[-1], parts[-1])\n    # Every _MODIFIERS name is in CUA's modifier_vk table (keyboard.rs:811-819).\n    if any(m not in _MODIFIERS for m in mods):\n        return None\n    if len(key) != 1 and key not in _CUA_KEYS:\n        return None\n    if mods:\n        return \"hotkey\", {\"keys\": [*mods, key]}\n    return \"press_key\", {\"key\": key}\n\n\ndef _key_target_process(store: RefStore, ref: str | None, window: str | None) -> str:\n    \"\"\"The process that would receive a shortcut (for quiet_limits).\"\"\"\n    if ref:\n        return _safe(lambda: store.resolve(ref).process, \"\") or \"\"\n    if window and window.strip().startswith(\"#\"):\n        # b9: a handle's process comes from the Win32 binding - no UIA scan,\n        # no extra driver list_windows round-trip (the b5t7 E2 finding).\n        try:\n            binding = _window_identity(int(window.strip()[1:], 0))\n        except ValueError:\n            binding = None\n        return (binding or {}).get(\"process\", \"\") or \"\"\n    if window:\n        w = _safe(lambda: find_window(window), None)\n        return _process_name(w) if w is not None else \"\"\n    return \"\"\n\n\ndef _top_level_titles(pid: int) -> tuple[str, ...]:\n    \"\"\"Visible top-level window titles of one process (bounded, read-only).\"\"\"\n    import ctypes\n    from ctypes import wintypes\n    user32 = ctypes.windll.user32\n    titles: list[str] = []\n    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)\n\n    def visit(hwnd: Any, _lparam: Any) -> bool:\n        owner = wintypes.DWORD()\n        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(owner))\n        if owner.value == pid and user32.IsWindowVisible(hwnd):\n            buf = ctypes.create_unicode_buffer(256)\n            user32.GetWindowTextW(hwnd, buf, 256)\n            titles.append(buf.value)\n        return len(titles) < 64\n    user32.EnumWindows(proc(visit), 0)\n    return tuple(sorted(titles))\n\n\ndef _observable_state() -> tuple[Any, ...]:\n    \"\"\"What a shortcut can visibly change: the foreground window and its\n    title, the windows of its process, and the focused element.\"\"\"\n    def read() -> tuple[Any, ...]:\n        import ctypes\n        from ctypes import wintypes\n        user32 = ctypes.windll.user32\n        fg = int(user32.GetForegroundWindow() or 0)\n        buf = ctypes.create_unicode_buffer(256)\n        user32.GetWindowTextW(fg, buf, 256)\n        pid = wintypes.DWORD()\n        user32.GetWindowThreadProcessId(fg, ctypes.byref(pid))\n        ua = _require_uia()\n        focused = _safe(lambda: ua.GetFocusedControl(), None)\n        focus_sig = (_safe(lambda: focused.ControlTypeName, \"\"), _safe(lambda: focused.Name, \"\"),\n                     _safe(lambda: focused.GetValuePattern().Value, None)) if focused else None\n        return (fg, buf.value, _top_level_titles(pid.value) if pid.value else (), focus_sig)\n    return _safe(read, ()) or ()\n\n\ndef _observed_change(before: tuple[Any, ...], timeout: float = 0.8) -> list[str] | None:\n    \"\"\"Poll briefly for a visible change after delivered input: the names of\n    what changed, [] when nothing did, None when the state cannot be read.\"\"\"\n    if not before:\n        return None\n    labels = (\"foreground window\", \"foreground title\", \"process windows\", \"focused element\")\n    deadline = time.monotonic() + timeout\n    while True:\n        time.sleep(0.1)\n        after = _observable_state()\n        if not after:\n            return None\n        changed = [label for label, a, b in zip(labels, before, after) if a != b]\n        if changed or time.monotonic() >= deadline:\n            return changed\n\n\ndef _activate_ref(entry: ElementRef, keys: str) -> dict[str, Any]:\n    \"\"\"Enter means activate this exact target, not inject a global key.\n\n    SelectionItem.Select is deliberately absent: selecting a suggestion/file\n    is not opening it. Never infer a form's default button from an edit field.\n    \"\"\"\n    _guard(entry)\n    if entry.role not in {\n            \"button\", \"link\", \"menuitem\", \"listitem\", \"treeitem\", \"option\"}:\n        raise InteractiveRequired(\n                            \"This target has no supported semantic Enter mapping\",\n                            hint=\"Target the observed action or suggestion itself, not its text field.\",\n                            code=\"background_no_semantic_action\")\n    from .uia import quiet_control\n    control = quiet_control(entry.control)\n    pattern = _safe(lambda: control.GetInvokePattern(), None)\n    if pattern is not None:\n        action, method = pattern.Invoke, \"invoke\"\n    else:\n        legacy = _safe(lambda: control.GetLegacyIAccessiblePattern(), None)\n        if legacy is None or not _safe(lambda: legacy.DefaultAction, \"\"):\n            raise InteractiveRequired(\n                                \"This target does not expose an activation action\",\n                                hint=\"No keyboard event or default action was sent.\",\n                                code=\"background_no_semantic_action\")\n        action, method = legacy.DoDefaultAction, \"legacy-default-action\"\n    _overlay_aim_ref(entry)\n    try:\n        action()\n    except Exception as exc:\n        raise ProtocolError(ErrorCode.INTERNAL, \"Target activation result is unknown\",\n                            hint=\"Observe before another activation.\",\n                            effect_state=EffectState.UNKNOWN) from exc\n    _overlay_pulse()\n    return _result(EffectState.UNKNOWN, verified=False, keys=keys,\n                   sent_to=entry.describe(), via=\"uia-pattern\", method=method,\n                   note=\"Activation was dispatched; observe the target's resulting state.\")\n\n\n_KEY_ALIASES = {\n    \"enter\": \"{Enter}\", \"return\": \"{Enter}\", \"tab\": \"{Tab}\", \"esc\": \"{Esc}\",\n    \"escape\": \"{Esc}\", \"space\": \" \", \"backspace\": \"{Back}\", \"back\": \"{Back}\",\n    \"delete\": \"{Delete}\", \"del\": \"{Delete}\", \"home\": \"{Home}\", \"end\": \"{End}\",\n    \"pageup\": \"{PageUp}\", \"pagedown\": \"{PageDown}\", \"up\": \"{Up}\",\n    \"down\": \"{Down}\", \"left\": \"{Left}\", \"right\": \"{Right}\", \"insert\": \"{Insert}\",\n    # fx4: the rest of CUA's key names (keyboard.rs:860-913) in SendKeys spelling.\n    \"ins\": \"{Insert}\", \"pgup\": \"{PageUp}\", \"pgdn\": \"{PageDown}\",\n    \"capslock\": \"{Capital}\", \"numlock\": \"{NumLock}\",\n    \"ctrl\": \"{Ctrl}\", \"control\": \"{Ctrl}\", \"shift\": \"{Shift}\", \"alt\": \"{Alt}\",\n    \"win\": \"{Win}\", \"windows\": \"{Win}\", \"meta\": \"{Win}\", \"command\": \"{Win}\", \"cmd\": \"{Win}\",\n}\n# `uiautomation.SendKeys` uses brace syntax for held modifiers - `{Ctrl}a` -\n# not the `^a` shorthand of VBScript/Win32 SendKeys. Emitting `^` and `+` sent\n# those characters as literal text, so every combination was silently inert:\n# `Ctrl+Shift+N` in File Explorer typed nothing and created no folder, while\n# the call still reported success. A unit test on the string transformation\n# passed throughout, because it asserted the wrong target syntax.\n_MODIFIERS = {\"ctrl\": \"{Ctrl}\", \"control\": \"{Ctrl}\", \"shift\": \"{Shift}\",\n              \"alt\": \"{Alt}\", \"win\": \"{Win}\", \"cmd\": \"{Win}\",\n              # fx4: CUA's other modifier_vk spellings (keyboard.rs:811-819).\n              \"menu\": \"{Alt}\", \"option\": \"{Alt}\", \"meta\": \"{Win}\",\n              \"windows\": \"{Win}\", \"command\": \"{Win}\"}\n\n\ndef _to_sendkeys(keys: str) -> str:\n    parts = [p.strip().lower() for p in keys.replace(\"-\", \"+\").split(\"+\") if p.strip()]\n    if not parts:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, f\"empty key spec {keys!r}\")\n    mods = [_MODIFIERS[p] for p in parts[:-1] if p in _MODIFIERS]\n    if len(mods) != len(parts) - 1:\n        unknown = [p for p in parts[:-1] if p not in _MODIFIERS]\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED, f\"unknown modifier(s): {', '.join(unknown)}\",\n            hint=\"Use ctrl, shift, alt or win.\")\n    last = parts[-1]\n    base = _KEY_ALIASES.get(last)\n    if base is None:\n        if len(last) == 1:\n            base = last\n        elif last.startswith(\"f\") and last[1:].isdigit():\n            base = \"{\" + last.upper() + \"}\"\n        else:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED, f\"unknown key {last!r}\",\n                hint=\"Try Enter, Tab, Esc, F5, a single character, or a combo \"\n                     \"like Ctrl+S.\")\n    return \"\".join(mods) + base\n\n\n# --- scrolling ---------------------------------------------------------------\n\ndef _scroll_percent(sp: Any) -> tuple[float, float]:\n    \"\"\"(horizontal, vertical) scroll position, or (-1, -1) if unavailable.\"\"\"\n    h = _safe(lambda: float(sp.HorizontalScrollPercent), -1.0)\n    v = _safe(lambda: float(sp.VerticalScrollPercent), -1.0)\n    return (h if h is not None else -1.0, v if v is not None else -1.0)\n\n\ndef _wheel_over(ua: Any, control: Any, direction: str, amount: int) -> bool:\n    \"\"\"Send a real wheel event over an element, restoring the cursor after.\n\n    The pointer has to be over the target for the wheel to reach it, which\n    means borrowing the user's mouse for a moment. Putting it back is not\n    cosmetic: leaving the cursor parked somewhere it was not is exactly the\n    kind of interference desktop automation should minimise.\n    \"\"\"\n    if BACKGROUND_ONLY.get():\n        return False\n    rect = _safe(lambda: control.BoundingRectangle, None)\n    if rect is None or rect.right <= rect.left:\n        return False\n    cx = (rect.left + rect.right) // 2\n    cy = (rect.top + rect.bottom) // 2\n    left, top, right, bottom = _virtual_screen()\n    if not (left <= cx <= right and top <= cy <= bottom):\n        return False\n\n    saved = _safe(lambda: ua.GetCursorPos(), None)\n    try:\n        _safe(lambda: ua.SetCursorPos(cx, cy))\n        time.sleep(0.1)\n        if direction == \"down\":\n            ua.WheelDown(amount)\n        elif direction == \"up\":\n            ua.WheelUp(amount)\n        else:\n            # Horizontal wheel: shift+wheel is the conventional mapping.\n            ua.SendKeys(\"{Shift down}\", waitTime=0)\n            try:\n                (ua.WheelDown if direction == \"right\" else ua.WheelUp)(amount)\n            finally:\n                ua.SendKeys(\"{Shift up}\", waitTime=0)\n        return True\n    except Exception:\n        return False\n    finally:\n        if saved:\n            _safe(lambda: ua.SetCursorPos(saved[0], saved[1]))\n\n\ndef scroll(store: RefStore, *, ref: str | None = None, direction: str = \"down\",\n           amount: int = 3, by: str = \"line\", window: str | None = None,\n           x: float | None = None, y: float | None = None,\n           delivery_mode: str | None = None) -> dict[str, Any]:\n    \"\"\"Scroll, then report how far it actually moved.\n\n    A control can accept a scroll request and not move: it may already be at\n    the limit, or have no scrollable extent on that axis at all. Word-wrapped\n    Notepad is the everyday case — it reports success for `right` and `left`\n    while nothing whatsoever happens. `ScrollPattern` exposes the position as a\n    percentage, so the claim can be checked instead of assumed.\n\n    A driver ref, `window` or `x`/`y` take CUA's scroll instead (B10); CUA\n    does not verify a scroll, so that route reports unknown.\n    \"\"\"\n    driver = _driver_scroll(store, ref=ref, direction=direction, amount=amount,\n                            by=by, window=window, x=x, y=y, delivery_mode=delivery_mode)\n    if driver is not None:\n        return driver\n    ua = _require_uia()\n    if ref:\n        entry = store.resolve(ref)\n        _guard(entry)\n        control = entry.control\n        if BACKGROUND_ONLY.get():\n            from .uia import quiet_control\n            control = quiet_control(control)\n        sp = _safe(lambda: control.GetScrollPattern(), None)\n        if sp is not None:\n            horizontal = direction in (\"left\", \"right\")\n            axis_ok = _safe(\n                lambda: bool(sp.HorizontallyScrollable if horizontal\n                             else sp.VerticallyScrollable), True)\n            if not axis_ok:\n                # Not a failure, a fact: word-wrapped Notepad has no\n                # horizontal extent at all. Saying \"committed\" here is a lie.\n                return _result(\n                    EffectState.NONE, method=\"scroll_pattern\",\n                    direction=direction, amount=amount, moved={\"h\": 0.0, \"v\": 0.0},\n                    note=f\"this control is not scrollable {direction} \"\n                         f\"({'horizontally' if horizontal else 'vertically'} \"\n                         f\"scrollable = False)\")\n\n            before = _scroll_percent(sp)\n            vert = 1 if direction == \"down\" else -1 if direction == \"up\" else 0\n            horiz = 1 if direction == \"right\" else -1 if direction == \"left\" else 0\n            _safe(lambda: sp.Scroll(horizontalAmount=horiz * amount,\n                                    verticalAmount=vert * amount))\n            time.sleep(0.15)\n            after = _scroll_percent(sp)\n            method = \"scroll_pattern\"\n\n            # `ScrollPattern.Scroll` reports success and moves nothing on some\n            # providers (Notepad's edit control among them). A real wheel event\n            # over the element does work, so fall back rather than accept a\n            # scroll that did not happen.\n            if after == before and before[0] >= 0:\n                if _wheel_over(ua, entry.control, direction, amount):\n                    time.sleep(0.25)\n                    after = _scroll_percent(sp)\n                    method = \"wheel_fallback\"\n\n            moved_h = round(after[0] - before[0], 2) if before[0] >= 0 else None\n            moved_v = round(after[1] - before[1], 2) if before[1] >= 0 else None\n            res = _result(EffectState.COMMITTED, method=method,\n                          direction=direction, amount=amount,\n                          percent_from={\"h\": before[0], \"v\": before[1]},\n                          percent_to={\"h\": after[0], \"v\": after[1]},\n                          moved={\"h\": moved_h, \"v\": moved_v})\n            if moved_h == 0.0 and moved_v == 0.0:\n                res[\"effect_state\"] = EffectState.NONE.value\n                res[\"note\"] = (f\"nothing moved: already at the {direction} \"\n                               f\"limit, or the content fits\")\n            return res\n        require_interactive(\"Mouse-wheel fallback\")\n        _safe(lambda: entry.control.SetFocus())\n    require_interactive(\"Mouse-wheel input\")\n    delta = amount if direction == \"up\" else -amount\n    try:\n        ua.WheelUp(delta) if delta > 0 else ua.WheelDown(-delta)\n    except Exception as exc:\n        raise ProtocolError(ErrorCode.INTERNAL, f\"scroll failed: {exc}\",\n                            effect_state=EffectState.UNKNOWN) from exc\n    return _result(EffectState.COMMITTED, method=\"wheel\",\n                   direction=direction, amount=amount)\n\n\ndef _driver_scroll(store: RefStore, *, ref: str | None, direction: str, amount: int,\n                   by: str, window: str | None, x: float | None,\n                   y: float | None, delivery_mode: str | None = None) -> dict[str, Any] | None:\n    \"\"\"B10: desktop.scroll on CUA's scroll (impl_.rs:6309-6691 at 815dfd96).\n\n    A token ref scrolls the element (UIA ScrollPattern in background), a\n    window gets posted WM_VSCROLL/WM_HSCROLL, x/y with a window aim a nested\n    surface (foreground only, so DR-02 applies) and x/y alone are CUA's\n    desktop scope, a real wheel. Background first, as CUA defaults. None\n    keeps the Python path: a Python ref, or no target at all.\"\"\"\n    entry = store.resolve(ref) if ref else None\n    if entry is not None and not entry.element_token:\n        return None\n    if entry is None and not window and x is None and y is None:\n        return None\n    from . import driver_backend\n    # CUA posts SB_LINEDOWN for a direction it does not know (impl_.rs:6655),\n    # so only its schema's vocabulary (:6331-6346) is sent.\n    if (direction not in (\"up\", \"down\", \"left\", \"right\") or by not in (\"line\", \"page\")\n            or not 1 <= amount <= 50 or (x is None) != (y is None)\n            or (entry is not None and x is not None)):\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"CUA's scroll takes direction up|down|left|right, by line|page, amount \"\n            \"1-50 and x with y (not with a ref); nothing was sent\",\n            effect_state=EffectState.NONE)\n    if not driver_backend.supports(\"scroll\"):\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"scrolling a driver ref, a window or a point needs the driver's scroll; \"\n            \"nothing was sent\",\n            hint=\"Observe with AUTOSKILL_DRIVER=off to scroll a Python ref.\",\n            effect_state=EffectState.NONE)\n    params: dict[str, Any] = {\"direction\": direction, \"amount\": amount, \"by\": by}\n    factory = None\n    first = \"background\"\n    # perf1: no pointer motion - CUA's ScrollTool makes no overlay call (impl_.rs:6309-6873).\n    if entry is not None:\n        _guard(entry)\n        target = entry.describe()\n    else:\n        from types import SimpleNamespace\n        if window:\n            w = _driver_window(window)\n            hwnd = int(_safe(lambda: w.NativeWindowHandle, 0) or 0) if w else 0\n            pid = int(_safe(lambda: w.ProcessId, 0) or 0) if w else 0\n            if not hwnd or not pid:\n                raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND,\n                                    f\"no window matching {window!r} to scroll\",\n                                    hint=\"Run `auto windows` and target it by #handle.\",\n                                    effect_state=EffectState.NONE)\n            target = f\"window {(_safe(lambda: w.Name, '') or window)!r}\"\n            fixed = {\"pid\": pid, \"window_id\": hwnd}\n        else:\n            # CUA's desktop scope sends a real wheel at the screen point.\n            require_interactive(\"Mouse-wheel input\")\n            first, pid, hwnd = \"foreground\", 0, 0\n            target = f\"screen ({x},{y})\"\n            fixed = {\"scope\": \"desktop\"}\n        if x is not None:\n            fixed.update(x=x, y=y)\n        entry = SimpleNamespace(ref=target, control=None, element_token=\"\",\n                                window_pid=pid, top_window=hwnd, rect=None,\n                                describe=lambda: target)\n\n        def factory() -> dict[str, Any]:\n            return {**fixed, **params}\n    res = _driver_action(entry, \"scroll\", params, verb=\"scroll\", pixel_params=factory,\n                         first=_requested_first(delivery_mode, first, \"Foreground scroll\"))\n    if res is None:\n        return None\n    res.update(direction=direction, amount=amount, by=by, sent_to=target)\n    return res\n\n\n# --- b11: CUA's drag ---------------------------------------------------------\n\ndef _drag_vocab_error() -> ProtocolError:\n    return ProtocolError(\n        ErrorCode.UNSUPPORTED,\n        \"CUA's drag takes button left|right|middle, duration_ms 0-10000, \"\n        \"steps 1-200, a ref with to_ref or to_x/to_y, or a window (or the \"\n        \"screen) with from_x, from_y, to_x and to_y; nothing was sent\",\n        effect_state=EffectState.NONE)\n\n\ndef _drag(store: RefStore, *, ref: str | None = None,\n          to_ref: str | None = None, window: str | None = None,\n          from_x: float | None = None, from_y: float | None = None,\n          to_x: float | None = None, to_y: float | None = None,\n          button: str | None = None, duration_ms: int | None = None,\n          steps: int | None = None,\n          from_zoom: bool = False, delivery_mode: str | None = None) -> dict[str, Any]:\n    \"\"\"b11 (B11): CUA's pixel drag, driver-only (impl_.rs:7597-7975 at\n    815dfd96). Drag is PIXEL-ONLY: no element_token exists (CUA's own batch\n    refuses element-named drag, batch_tools.rs:1718-1722) and no capture_id\n    (the fresh NATIVE capture below establishes screenshot scale 1.0 for the\n    session, so CUA's ratio multiply is a no-op - snapshot_store.rs:498-513).\n\n    Three forms: (1) ref + to_ref/to_x,to_y - the source rect centre (and\n    the drop point) map through a FRESH native capture (the b5t3 origin\n    logic minus the capture id); (2) window + window-local pixels, passed\n    through as CUA's own keys (from_zoom sends the last zoom's pixels);\n    (3) screen-absolute from/to = CUA's scope:desktop, ALWAYS real SendInput\n    (impl_.rs:7638-7688), so require_interactive fires FIRST.\n\n    CUA's runtime does NOT enforce its own schema bounds (u64_or reads,\n    :7718-7720), so out-of-vocabulary values are refused HERE, before any\n    input. modifier is never exposed (admitted and ignored on Windows).\n    Every success is CUA's unverifiable -> unknown (K2c). The real pointer\n    returns (M1: CUA restores it, mouse.rs:887; _saved_cursor belts it).\"\"\"\n    from . import driver_backend\n    coords = (from_x, from_y, to_x, to_y)\n    have_coords = all(v is not None for v in coords)\n    # The pre-input vocabulary/form gate (the b5t1 pairs rule; b10 wording).\n    if (button is not None and button not in (\"left\", \"right\", \"middle\")\n            or (duration_ms is not None\n                and (isinstance(duration_ms, bool)\n                     or not 0 <= duration_ms <= 10000))\n            or (steps is not None\n                and (isinstance(steps, bool) or not 1 <= steps <= 200))\n            or (ref is not None and (window is not None or from_x is not None))\n            or (to_ref is not None and ref is None)\n            or (ref is None and window is None and not have_coords)\n            or (window is not None and not have_coords)\n            or (from_zoom and (ref is not None or window is None))):\n        raise _drag_vocab_error()\n    if not driver_backend.supports(\"drag\"):\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"dragging needs the driver's drag; nothing was sent\",\n            hint=\"Observe with AUTOSKILL_DRIVER=off; there is no Python \"\n                 \"drag path.\",\n            effect_state=EffectState.NONE)\n\n    options: dict[str, Any] = {}\n    if button is not None:\n        options[\"button\"] = str(button)\n    if duration_ms is not None:\n        options[\"duration_ms\"] = int(duration_ms)\n    if steps is not None:\n        options[\"steps\"] = int(steps)\n\n    from types import SimpleNamespace\n\n    if ref is not None:\n        src = store.resolve(ref)\n        _guard(src)\n        if not src.element_token:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"{src.ref} is a Python ref; a drag needs a driver ref from \"\n                \"observe; there is no Python drag path; nothing was sent\",\n                effect_state=EffectState.NONE)\n        r = src.rect\n        if r is None or not r[2] > r[0] or not r[3] > r[1]:\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_VISIBLE,\n                f\"{src.describe()} has no frame for a pixel drag\",\n                hint=\"Observe again; a pixel drag needs the element's frame.\",\n                effect_state=EffectState.NONE)\n        from_pt = ((r[0] + r[2]) / 2.0, (r[1] + r[3]) / 2.0)\n        if to_ref is not None:\n            dst = store.resolve(to_ref)\n            _guard(dst)\n            d = dst.rect\n            if d is None or not d[2] > d[0] or not d[3] > d[1]:\n                raise ProtocolError(\n                    ErrorCode.TARGET_NOT_VISIBLE,\n                    f\"{dst.describe()} has no frame for a pixel drag\",\n                    hint=\"Observe again; a pixel drag needs the drop \"\n                         \"target's frame.\",\n                    effect_state=EffectState.NONE)\n            to_pt = ((d[0] + d[2]) / 2.0, (d[1] + d[3]) / 2.0)\n        else:\n            to_pt = None          # to_x/to_y are window-local: pass through\n        _overlay_aim_rect(src)\n        pid, hwnd = int(src.window_pid), int(src.top_window)\n\n        def factory() -> dict[str, Any]:\n            # A FRESH native capture per delivery attempt (the pixel_params\n            # factory, b5t3): origin from the reply's frame/screenshot_frame\n            # pair, else the DWM frame + 1 (impl_.rs:227-249). NO capture_id\n            # rides the call - drag has no admission (S1 section 4).\n            from . import captures\n            cap = captures.capture_for_action(\n                f\"drag:{pid}:{hwnd}\", pid, hwnd, max_image_dimension=0)\n            origin = getattr(cap, \"frame_origin\", None)\n            if origin is None:\n                frame = captures._dwm_frame(hwnd)\n                if frame is None:\n                    raise ProtocolError(\n                        ErrorCode.WINDOW_NOT_FOUND,\n                        \"The target window cannot be resolved\",\n                        effect_state=EffectState.NONE)\n                origin = (frame[0] + 1, frame[1] + 1)\n            out: dict[str, Any] = {\n                \"pid\": pid, \"window_id\": hwnd,\n                \"from_x\": round(from_pt[0] - origin[0]),\n                \"from_y\": round(from_pt[1] - origin[1])}\n            if to_pt is not None:\n                out[\"to_x\"] = round(to_pt[0] - origin[0])\n                out[\"to_y\"] = round(to_pt[1] - origin[1])\n            else:\n                out[\"to_x\"], out[\"to_y\"] = to_x, to_y\n            out.update(options)\n            return out\n\n        entry: Any = src\n        target = src.describe()\n        first = \"background\"\n        fixed: dict[str, Any] | None = None\n    elif window is not None:\n        w = _driver_window(window)\n        hwnd = int(_safe(lambda: w.NativeWindowHandle, 0) or 0) if w else 0\n        pid = int(_safe(lambda: w.ProcessId, 0) or 0) if w else 0\n        if not hwnd or not pid:\n            raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND,\n                                f\"no window matching {window!r} to drag\",\n                                hint=\"Run `auto windows` and target it by \"\n                                     \"#handle.\",\n                                effect_state=EffectState.NONE)\n        title = (_safe(lambda: w.Name, \"\") or window)\n        target = f\"window '{title}'\"\n        fixed = {\"pid\": pid, \"window_id\": hwnd, \"from_x\": from_x,\n                 \"from_y\": from_y, \"to_x\": to_x, \"to_y\": to_y}\n        if from_zoom:\n            fixed[\"from_zoom\"] = True\n        fixed.update(options)\n        entry = SimpleNamespace(ref=target, control=None, element_token=\"\",\n                                window_pid=pid, top_window=hwnd, rect=None,\n                                describe=lambda: target)\n\n        def factory() -> dict[str, Any]:\n            if not from_zoom:\n                from . import captures\n                captures.capture_for_action(f\"drag:{pid}:{hwnd}\", pid, hwnd,\n                                            max_image_dimension=0)\n            return dict(fixed)\n\n        first = \"background\"\n    else:\n        # CUA's desktop scope is ALWAYS real SendInput (impl_.rs:7638-7688)\n        # - the b10 desktop precedent: interactive opt-in BEFORE anything.\n        require_interactive(\"Drag input\")\n        target = f\"screen ({from_x:.0f},{from_y:.0f})\" \\\n                 f\"→({to_x:.0f},{to_y:.0f})\"\n        fixed = {\"scope\": \"desktop\", \"from_x\": from_x, \"from_y\": from_y,\n                 \"to_x\": to_x, \"to_y\": to_y}\n        fixed.update(options)\n        entry = SimpleNamespace(ref=target, control=None, element_token=\"\",\n                                window_pid=0, top_window=0, rect=None,\n                                describe=lambda: target)\n\n        def factory() -> dict[str, Any]:\n            return dict(fixed)\n\n        first = \"foreground\"\n\n    with _saved_cursor():\n        res = _driver_action(entry, \"drag\", {}, verb=\"drag\",\n                             pixel_params=factory,\n                             first=_requested_first(delivery_mode, first, \"Foreground drag\"))\n    if res is None:\n        # try_call None before any dispatch: a token ref has no Python rung.\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"the driver is unavailable and drag has no Python path; \"\n            \"no input was sent\",\n            effect_state=EffectState.NONE)\n    _overlay_pulse(verified=bool(res.get(\"verified\")))\n    res[\"sent_to\"] = target\n    return res\n\n\ndef drag(store: RefStore, *, ref: str | None = None,\n         to_ref: str | None = None, window: str | None = None,\n         from_x: float | None = None, from_y: float | None = None,\n         to_x: float | None = None, to_y: float | None = None,\n         button: str | None = None, duration_ms: int | None = None,\n         steps: int | None = None,\n         from_zoom: bool = False, delivery_mode: str | None = None) -> dict[str, Any]:\n    with foreground_returned():\n        return _drag(store, ref=ref, to_ref=to_ref, window=window,\n                     from_x=from_x, from_y=from_y, to_x=to_x, to_y=to_y,\n                     button=button, duration_ms=duration_ms, steps=steps,\n                     from_zoom=from_zoom, delivery_mode=delivery_mode)\n\n\n# --- windows & apps ----------------------------------------------------------\n\ndef list_windows(include_hidden: bool = False, *,\n                 via_driver: bool = True) -> list[dict[str, Any]]:\n    \"\"\"Public window inventory.\n\n    The native driver's merged UIA+Win32 enumeration is used first when it is\n    enabled and only the visible listing is asked for; it also returns real\n    class/process data for owned dialogs that the Python UIA walk merges as\n    anonymous `win32-discovered` rows. The Python path stays the all/hidden\n    path and the fallback: an inventory sends no input, so an unavailable or\n    refusing driver fails open to exactly today's listing (plan 0.3.3).\n    \"\"\"\n    if via_driver and not include_hidden:\n        rows = _driver_window_rows()\n        if rows is not None:\n            return rows\n    return _list_windows_python(include_hidden)\n\n\ndef _list_windows_python(include_hidden: bool = False) -> list[dict[str, Any]]:\n    ua = _require_uia()\n    out: list[dict[str, Any]] = []\n    listed_handles: set[int] = set()\n    root = ua.GetRootControl()\n    for w in _safe(lambda: root.GetChildren(), []) or []:\n        name = (_safe(lambda: w.Name, \"\") or \"\").strip()\n        if not name and not include_hidden:\n            continue\n        if _safe(lambda: bool(w.IsOffscreen), False) and not include_hidden:\n            continue\n        # b4e: the b4d one-hwnd-one-window rule carried into the listing —\n        # UIA can hand back the same window twice (b4c 22-c-dbl3), and\n        # CUA's list_windows never lists one hwnd twice (win32/windows.rs:\n        # 62-79). Only listed rows consume a handle, so a duplicate that a\n        # filter already dropped stays dropped.\n        handle = _safe(lambda: w.NativeWindowHandle, 0) or 0\n        if handle and handle in listed_handles:\n            continue\n        if handle:\n            listed_handles.add(handle)\n        r = _safe(lambda: w.BoundingRectangle, None)\n        out.append({\n            \"title\": name,\n            \"class\": _safe(lambda: w.ClassName, \"\") or \"\",\n            \"process\": _process_name(w),\n            \"handle\": handle,\n            \"rect\": [r.left, r.top, r.right, r.bottom] if r else None,\n            \"pid\": int(_safe(lambda: w.ProcessId, 0) or 0),   # fx5: CUA's row pid\n        })\n    # UIA's root children can miss owned modal dialogs (#32770) — the Excel\n    # Save As case: foreground, yet absent from this listing while it blocked\n    # every window-level action. Merge what Win32 sees so the listing and the\n    # targeting agree on what exists.\n    seen = {w.get(\"handle\") for w in out}\n    import ctypes\n    user32 = ctypes.windll.user32\n    for h in _win32_windows_matching(\"\"):\n        if h in seen:\n            continue\n        buf = ctypes.create_unicode_buffer(256)\n        user32.GetWindowTextW(h, buf, 256)\n        owner = ctypes.c_ulong(0)\n        user32.GetWindowThreadProcessId(h, ctypes.byref(owner))\n        out.append({\n            \"title\": buf.value,\n            \"class\": \"#32770-or-win32\",\n            \"process\": \"\",\n            \"handle\": h,\n            \"rect\": None,\n            \"pid\": int(owner.value),   # fx5: CUA's row pid\n            \"note\": \"win32-discovered (invisible to UIA root)\",\n        })\n    return out\n\n\ndef _process_name(control: Any) -> str:\n    pid = _safe(lambda: control.ProcessId, None)\n    if not pid:\n        return \"\"\n    try:\n        import psutil\n        return psutil.Process(pid).name()\n    except Exception:\n        return \"\"\n\n\ndef _process_name_for_pid(pid: Any) -> str:\n    \"\"\"Executable basename for a pid, read locally. Driver rows carry their\n    own `app_name`, but policy identity must come from this machine's own\n    process table, never from a driver-supplied name (T2 constraint).\"\"\"\n    if not isinstance(pid, int) or isinstance(pid, bool) or pid <= 0:\n        return \"\"\n    try:\n        import psutil\n        return psutil.Process(pid).name()\n    except Exception:\n        return \"\"\n\n\ndef _driver_window_rows() -> list[dict[str, Any]] | None:\n    \"\"\"Visible window inventory via the native driver, or None.\n\n    None means unavailable or refused: the caller fails open to the Python\n    listing, which an inventory without input may always do. Row shape is the\n    public key contract (fx5 added CUA's pid); the pid used for `process` is the enriched\n    native pid (a local Win32 read inside the driver), not `app_name`.\n    \"\"\"\n    from . import driver_backend\n    reply = driver_backend.try_call(\"list_windows\", {\"include_dialogs\": True})\n    if reply is None or not reply.get(\"ok\"):\n        return None\n    windows = (reply.get(\"result\") or {}).get(\"windows\")\n    if not isinstance(windows, list):\n        return None\n    out: list[dict[str, Any]] = []\n    for w in windows:\n        if not isinstance(w, dict):\n            continue\n        handle = w.get(\"window_id\")\n        if not isinstance(handle, int) or isinstance(handle, bool):\n            continue\n        rect = w.get(\"rect\")\n        pid = w.get(\"native_pid\") or w.get(\"pid\")\n        out.append({\n            \"title\": w.get(\"title\") if isinstance(w.get(\"title\"), str) else \"\",\n            \"class\": w.get(\"class\") if isinstance(w.get(\"class\"), str) else \"\",\n            \"process\": _process_name_for_pid(pid),\n            \"handle\": handle,\n            \"rect\": list(rect) if isinstance(rect, list) and len(rect) == 4 else None,\n            \"pid\": pid if isinstance(pid, int) and not isinstance(pid, bool) else 0,  # fx5: CUA's row pid\n        })\n    return out\n\n\ndef _window_identity(handle: int) -> dict[str, Any] | None:\n    \"\"\"Local Win32 identity of one top-level window: no UIA, no driver.\n\n    This is what authorization binds before any SDK access. A dead or\n    foreign handle is simply absent (None) — the same answer `find_window`\n    gives for a window that no longer exists. GW_OWNER is 4, matching the\n    native enrichment's owner read.\n    \"\"\"\n    import ctypes\n    import ctypes.wintypes as _wt\n    user32 = ctypes.windll.user32\n    if not handle or not user32.IsWindow(handle):\n        return None\n    pid = _wt.DWORD(0)\n    if not user32.GetWindowThreadProcessId(handle, ctypes.byref(pid)) \\\n            or not pid.value:\n        return None\n    buf = ctypes.create_unicode_buffer(256)\n    user32.GetWindowTextW(handle, buf, 256)\n    owner = user32.GetWindow(handle, 4)          # GW_OWNER\n    owner_pid = _wt.DWORD(0)\n    if owner:\n        user32.GetWindowThreadProcessId(owner, ctypes.byref(owner_pid))\n    return {\n        \"handle\": int(handle),\n        \"pid\": int(pid.value),\n        \"title\": buf.value or \"\",\n        \"process\": _process_name_for_pid(int(pid.value)),\n        \"owner_handle\": int(owner) if owner else 0,\n        \"owner_pid\": int(owner_pid.value) if owner else 0,\n        \"owner_process\": _process_name_for_pid(int(owner_pid.value)) if owner else \"\",\n    }\n\n\ndef _driver_window(window: str) -> Any:\n    \"\"\"b5t7: the window for the CUA route, shaped like the UIA control the\n    route reads (NativeWindowHandle, ProcessId, Name, BoundingRectangle).\n\n    A '#<hwnd>' selector is read through Win32 only - the binding the\n    daemon's authorization uses before any SDK access (_window_identity).\n    AutoSkill's extra driver list_windows cross-check is not repeated: CUA's\n    own window_state and click validate the pid/window pair\n    (impl_.rs:1289-1310, :439-460). A title selector keeps find_window.\n    (b9: moved here from vision so the key route can use it without an\n    actions -> vision import.)\"\"\"\n    sel = window.strip()\n    if not sel.startswith(\"#\"):\n        return find_window(window)\n    try:\n        handle = int(sel[1:], 0)\n    except ValueError:\n        return None                 # the old path raises its own error\n    binding = _window_identity(handle)\n    if binding is None:\n        return None\n    from types import SimpleNamespace\n    from . import captures\n    r = captures._window_rect(handle)\n    rect = (SimpleNamespace(left=r[0], top=r[1], right=r[2], bottom=r[3])\n            if r else None)\n    import ctypes\n    cls = ctypes.create_unicode_buffer(256)\n    ctypes.windll.user32.GetClassNameW(handle, cls, 256)\n    return SimpleNamespace(NativeWindowHandle=handle, ProcessId=binding[\"pid\"],\n                           Name=binding[\"title\"], BoundingRectangle=rect,\n                           ClassName=cls.value, win32_view=True)\n\n\ndef window_identity(selector: str) -> dict[str, Any] | None:\n    \"\"\"Daemon authorization binding for a window selector, Win32 only.\n\n    Titles use the same first-visible-match rule `process_for_window` has\n    always used, so which window a selector binds does not change; the caller\n    additionally receives the actual title and the owner chain so the deny\n    list can judge the real target — including an owned dialog's real owner\n    process — before any driver access.\"\"\"\n    sel = (selector or \"\").strip()\n    if not sel:\n        return None\n    if sel.startswith(\"#\"):\n        try:\n            handle = int(sel[1:], 0)\n        except ValueError:\n            return None\n        return _window_identity(handle)\n    handle = (_win32_windows_matching(sel.lower()) or [0])[0]\n    return _window_identity(handle) if handle else None\n\n\ndef _win32_windows_matching(needle: str) -> list[int]:\n    \"\"\"Visible top-level window handles whose title contains needle, via\n    Win32 rather than UIA. Companion to find_window's fallback.\"\"\"\n    import ctypes\n    import ctypes.wintypes as _wt\n    user32 = ctypes.windll.user32\n    out: list[int] = []\n    kept: list[tuple[list, list]] = []          # keep callbacks alive\n\n    def _enum(h: int, _l: int) -> bool:\n        if user32.IsWindowVisible(h):\n            buf = ctypes.create_unicode_buffer(256)\n            user32.GetWindowTextW(h, buf, 256)\n            if buf.value and (not needle or needle in buf.value.lower()):\n                out.append(h)\n        return True\n\n    proc = ctypes.WINFUNCTYPE(ctypes.c_bool, _wt.HWND, _wt.LPARAM)(_enum)\n    kept.append((out, [proc]))                  # noqa: F841 — lifetime anchor\n    try:\n        user32.EnumWindows(proc, 0)\n    except Exception:\n        pass\n    return out\n\n\ndef process_for_window(selector: str) -> str | None:\n    \"\"\"Process name behind a window selector, via Win32 only.\n\n    The permission engine needs the process to apply the allow list, but\n    `_target_of` runs on the daemon thread and UIA may only be touched\n    from the single STA worker. Win32 has no apartment requirement, so\n    this resolves the owner without marshalling.\n\n    Why it matters: `_target_of` used to return `process=None` for every\n    verb aimed with `--window`, and the guarded-mode check is\n    `if process and not on_allow_list`. A None process skipped the check\n    entirely, so `auto type --window 'SomeApp'` ran without approval even\n    when SomeApp was not allow-listed.\n    \"\"\"\n    import ctypes\n    import ctypes.wintypes as _wt\n    user32 = ctypes.windll.user32\n    sel = (selector or \"\").strip()\n    if not sel:\n        return None\n\n    handle = 0\n    if sel.startswith(\"#\"):\n        try:\n            handle = int(sel[1:], 0)\n        except ValueError:\n            return None\n    else:\n        needle = sel.lower()\n        found: list[int] = []\n        kept: list[Any] = []\n\n        def _enum(h: int, _l: int) -> bool:\n            if user32.IsWindowVisible(h):\n                buf = ctypes.create_unicode_buffer(256)\n                user32.GetWindowTextW(h, buf, 256)\n                if buf.value and needle in buf.value.lower():\n                    found.append(h)\n            return True\n\n        proc = ctypes.WINFUNCTYPE(ctypes.c_bool, _wt.HWND, _wt.LPARAM)(_enum)\n        kept.append(proc)                      # lifetime anchor\n        try:\n            user32.EnumWindows(proc, 0)\n        except Exception:\n            return None\n        if not found:\n            return None\n        handle = found[0]\n\n    pid = ctypes.wintypes.DWORD(0)\n    try:\n        user32.GetWindowThreadProcessId(handle, ctypes.byref(pid))\n        if not pid.value:\n            return None\n        import psutil\n        return psutil.Process(pid.value).name()\n    except Exception:\n        return None\n\n\ndef find_window(selector: str) -> Any:\n    \"\"\"Resolve a window by stable handle or by title substring.\n\n    Titles are a moving target: Notepad becomes `*MyFile - Notepad` the moment\n    a character is typed, so a selector that worked one step earlier silently\n    stops matching. `auto windows` reports each window's handle, and a\n    selector of the form `#<handle>` targets it exactly — unaffected by\n    whatever the app renames itself to.\n    \"\"\"\n    ua = _require_uia()\n    sel = selector.strip()\n\n    if sel.startswith(\"#\"):\n        try:\n            handle = int(sel[1:], 0)\n        except ValueError:\n            raise ProtocolError(\n                ErrorCode.WINDOW_NOT_FOUND, f\"malformed window handle {sel!r}\",\n                hint=\"Use #<number> from `auto windows`, or a title substring.\")\n        return _control_from_bound_handle(handle, ua)\n\n    needle = sel.lower()\n    matches = []\n    seen_handles: set[int] = set()\n    for w in _safe(lambda: ua.GetRootControl().GetChildren(), []) or []:\n        name = (_safe(lambda: w.Name, \"\") or \"\")\n        if needle not in name.lower():\n            continue\n        # b4d: UIA handed back the SAME hwnd twice (b4c 22-c-dbl3,\n        # #33230118 listed twice) and the count turned one window into\n        # ambiguous_target. One NativeWindowHandle is one window,\n        # whichever source repeats it; different handles stay ambiguous.\n        handle = _safe(lambda w=w: w.NativeWindowHandle, 0)\n        if handle and handle in seen_handles:\n            continue\n        if handle:\n            seen_handles.add(handle)\n        matches.append((w, name))\n    if not matches:\n        # UIA's root children can miss owned modal dialogs (class #32770)\n        # that Win32 sees plainly — measured live: Excel's Save As dialog\n        # was the foreground window yet invisible to `auto windows`, so\n        # focus/observe declared it nonexistent while it blocked everything.\n        for h in _win32_windows_matching(needle):\n            ctl = _safe(lambda h=h: ua.ControlFromHandle(h), None)\n            if ctl is None:\n                continue\n            handle = _safe(lambda c=ctl: c.NativeWindowHandle, 0) or h\n            if handle in seen_handles:\n                continue\n            seen_handles.add(handle)\n            matches.append((ctl, _safe(lambda c=ctl: c.Name, \"\") or \"\"))\n    if not matches:\n        return None\n    if len(matches) > 1:\n        listing = \"; \".join(f\"#{_safe(lambda w=w: w.NativeWindowHandle, 0)} {n[:40]!r}\"\n                            for w, n in matches[:5])\n        raise ProtocolError(\n            ErrorCode.AMBIGUOUS_TARGET,\n            f\"{len(matches)} windows match {selector!r}\",\n            hint=f\"Target one exactly by handle: {listing}\")\n    return matches[0][0]\n\n\ndef _driver_identity_for(handle: int, binding: dict[str, Any]) -> None:\n    \"\"\"Cross-check the driver's enumeration against the local binding.\n\n    The comparison key is the pid: HWND reuse changes it, while titles may\n    legitimately change between two consecutive reads (typing), so a strict\n    title equality would refuse live targets. The authoritative title for\n    the deny check is the local read in the binding. A structured driver\n    failure is a final answer — the resolution must not silently replay in\n    Python on an identity it could not validate. A driver that is simply\n    unavailable (None reply, before any dispatch) leaves the local binding\n    in charge, which is today's fail-open path.\n    \"\"\"\n    from . import driver_backend\n    reply = driver_backend.try_call(\"list_windows\", {\"include_dialogs\": True})\n    if reply is None:\n        return\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.INTERNAL,\n            f\"driver window check failed: \"\n            f\"{error.get('code', 'driver_error')}: {error.get('message', '')}\",\n            effect_state=(EffectState.UNKNOWN\n                          if error.get(\"effect_state\") == \"unknown\"\n                          else EffectState.NONE))\n    windows = (reply.get(\"result\") or {}).get(\"windows\")\n    if not isinstance(windows, list):\n        raise ProtocolError(\n            ErrorCode.INTERNAL, \"driver window check returned malformed data\",\n            effect_state=EffectState.NONE)\n    row = next((w for w in windows\n                if isinstance(w, dict) and w.get(\"window_id\") == handle), None)\n    if row is None:\n        return  # the driver does not list this window; the local binding stands\n    row_pid = row.get(\"native_pid\") or row.get(\"pid\")\n    if row_pid != binding[\"pid\"]:\n        raise ProtocolError(\n            ErrorCode.WINDOW_NOT_FOUND,\n            f\"window #{handle} identity changed since authorization \"\n            f\"(bound pid {binding['pid']}, driver reports {row_pid})\",\n            hint=\"The window may have closed and its handle was reused. \"\n                 \"Re-list windows and target the current handle.\",\n            effect_state=EffectState.NONE)\n\n\ndef _control_from_bound_handle(handle: int, ua: Any) -> Any:\n    \"\"\"UIA control for an exact handle, identity validated end to end.\n\n    Replaces the UIA-root-children scan that missed owned modal dialogs\n    (#32770) — the G-W01 defect: Power BI's Create Table dialog failed by\n    handle while the title path saw the full tree. Every caller of\n    `find_window` expects a UIA control, so a validated SDK identity is\n    converted with `ControlFromHandle` on the UIA executor and re-checked;\n    only a pre-dispatch unavailable driver may proceed on the local binding\n    alone.\n    \"\"\"\n    binding = _window_identity(handle)\n    if binding is None:\n        return None\n    _driver_identity_for(handle, binding)\n    from .executor import uia_call\n    control = uia_call(lambda: _safe(lambda: ua.ControlFromHandle(handle), None))\n    if control is None:\n        return None\n    uia_pid = _safe(lambda: control.ProcessId, 0) or 0\n    if (_safe(lambda: control.NativeWindowHandle, 0) or 0) != handle \\\n            or (uia_pid != binding[\"pid\"] and not _console_host(control, uia_pid)):\n        raise ProtocolError(\n            ErrorCode.WINDOW_NOT_FOUND,\n            f\"window #{handle} changed while resolving it\",\n            hint=\"Re-list windows and target the current handle.\",\n            effect_state=EffectState.NONE)\n    return control if uia_pid == binding[\"pid\"] else _ClientPid(control, binding[\"pid\"])\n\n\ndef _console_host(control: Any, uia_pid: int) -> bool:\n    \"\"\"p3r D1: a classic console window - GetWindowThreadProcessId (and CUA) name the attached client (cmd.exe), UIA\n    names the console host process.\"\"\"\n    return (_safe(lambda: control.ClassName, \"\") == \"ConsoleWindowClass\"\n            and _process_name_for_pid(uia_pid).lower() in (\"conhost.exe\", \"openconsole.exe\"))\n\n\nclass _ClientPid:\n    \"\"\"The console's UIA control answering with the client pid every other route (and CUA) uses.\"\"\"\n\n    def __init__(self, control: Any, pid: int) -> None:\n        self._control, self.ProcessId = control, pid\n\n    def __getattr__(self, name: str) -> Any:\n        return getattr(self._control, name)\n\n\ndef _force_foreground(handle: int) -> None:\n    \"\"\"Raise a window past Windows' foreground lock.\n\n    SetForegroundWindow fails for background processes unless they received\n    input recently (focus-stealing prevention). Attaching our thread to the\n    input queues of both the current foreground window and the target makes\n    the raise legitimate to the OS — measured live in S88: plain SetActive\n    plus SetForegroundWindow left Excel buried under other windows, and real\n    clicks at its coordinates landed on whatever covered it.\n    \"\"\"\n    require_interactive(\"Foreground activation\")\n    import ctypes\n    user32 = ctypes.windll.user32\n    if not handle:\n        return\n    fg = user32.GetForegroundWindow()\n    this = ctypes.windll.kernel32.GetCurrentThreadId()\n    target = user32.GetWindowThreadProcessId(handle, None)\n    if not target:\n        return\n    attached_fg = False\n    try:\n        if fg and fg != handle:\n            fg_thread = user32.GetWindowThreadProcessId(fg, None)\n            if fg_thread:\n                attached_fg = bool(user32.AttachThreadInput(this, fg_thread, True))\n        user32.AttachThreadInput(this, target, True)\n        user32.BringWindowToTop(handle)\n        user32.SetForegroundWindow(handle)\n        user32.SetFocus(handle)\n    except Exception:\n        pass\n    finally:\n        try:\n            user32.AttachThreadInput(this, target, False)\n            if attached_fg:\n                user32.AttachThreadInput(\n                    this, user32.GetWindowThreadProcessId(fg, None), False)\n        except Exception:\n            pass\n\n\ndef focus_window(title_substring: str, *, force_fallback: bool = False) -> dict[str, Any]:\n    require_interactive(\"Focusing a window\")\n    try:\n        driver = _driver_focus_window(title_substring)\n    except ProtocolError as exc:\n        if not force_fallback or exc.error.code != ErrorCode.TARGET_NOT_VISIBLE:\n            raise\n    else:\n        if driver is not None:\n            return driver\n    w = find_window(title_substring)\n    if w is None:\n        raise ProtocolError(\n            ErrorCode.WINDOW_NOT_FOUND,\n            f\"no window whose title contains {title_substring!r}\",\n            hint=\"Run `auto windows` to see what is open.\")\n    _force_foreground(_safe(lambda: w.NativeWindowHandle, 0) or 0)\n    _safe(lambda: w.SetActive())\n    _safe(lambda: w.SetFocus())\n    return _result(EffectState.COMMITTED,\n                   title=_safe(lambda: w.Name, \"\") or \"\",\n                   process=_process_name(w))\n\n\ndef _driver_focus_window(selector: str) -> dict[str, Any] | None:\n    \"\"\"B14: desktop.focus --window on CUA's bring_to_front (impl_.rs:9657-9856 at 815dfd96): a minimized window is\n    restored, raised and given the foreground, and CUA reports whether it really became the foreground window.\n    None keeps the Python path: a driver without bring_to_front, a window this route cannot resolve, or the\n    driver unavailable before dispatch.\"\"\"\n    from . import driver_backend\n    if not driver_backend.supports(\"bring_to_front\"):\n        return None\n    w = _driver_window(selector)\n    hwnd = int(_safe(lambda: w.NativeWindowHandle, 0) or 0) if w else 0\n    pid = int(_safe(lambda: w.ProcessId, 0) or 0) if w else 0\n    if not hwnd or not pid:\n        return None\n    reply = driver_backend.try_call(\"bring_to_front\", {\"pid\": pid, \"window_id\": hwnd})\n    if reply is None:\n        return None\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.TARGET_NOT_VISIBLE,\n            f\"{selector!r} was not brought to the front: {error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            hint=\"Windows kept another window in the foreground. Click the target window yourself, \"\n                 \"or close whatever is covering it, then retry.\",\n            effect_state=EffectState.UNKNOWN if error.get(\"effect_state\") == \"unknown\"\n            else EffectState.NONE)\n    landed = reply.get(\"result\") or {}\n    return _result(EffectState.COMMITTED, title=_safe(lambda: w.Name, \"\") or \"\",\n                   process=_process_name(w), via=\"driver-bring_to_front\",\n                   previous_foreground=landed.get(\"previous_fg_hwnd\"),\n                   raised=landed.get(\"raised\"), restored=landed.get(\"restored\"))\n\n\ndef _window_index() -> dict[int, str]:\n    \"\"\"Handle -> title for every visible top-level window, right now.\"\"\"\n    ua = _require_uia()\n    out: dict[int, str] = {}\n    for w in _safe(lambda: ua.GetRootControl().GetChildren(), []) or []:\n        h = _safe(lambda: w.NativeWindowHandle, 0) or 0\n        if h:\n            out[h] = (_safe(lambda: w.Name, \"\") or \"\").strip()\n    return out\n\n\ndef _start_app_lookup(name: str) -> str | None:\n    \"\"\"Resolve a Start-menu app name (or accept a raw AppID with '!') to a\n    Store-app AppID launchable via shell:AppsFolder. Substring match,\n    case-insensitive, over Get-StartApps.\"\"\"\n    needle = name.lower().strip()\n    if not needle:\n        return None\n    if \"!\" in needle:\n        return name                      # already an AppID\n    try:\n        out = subprocess.run(\n            [\"powershell\", \"-NoProfile\", \"-Command\",\n             \"Get-StartApps | ConvertTo-Json -Compress\"],\n            capture_output=True, timeout=20, check=True, **hidden())\n        import json as _json\n        apps = _json.loads(out.stdout.decode(\"utf-8\", \"replace\") or \"[]\")\n        if isinstance(apps, dict):\n            apps = [apps]\n        # Exact-ish matches beat substring ones; .exe suffix tolerated.\n        key = needle.removesuffix(\".exe\")\n        exact = [a for a in apps\n                 if (a.get(\"Name\") or \"\").lower().removesuffix(\".exe\") == key]\n        partial = [a for a in apps if key in (a.get(\"Name\") or \"\").lower()]\n        for hit in (exact or partial):\n            appid = (hit.get(\"AppID\") or \"\").strip()\n            if appid and \"!\" in appid:\n                return appid\n    except Exception:\n        pass\n    return None\n\n\ndef _app_path_lookup(name: str) -> str | None:\n    \"\"\"Resolve a bare executable name through the App Paths registry keys\n    (HKCU then HKLM), the way the shell does. Returns None when absent.\"\"\"\n    if not name or Path(name).name != name:\n        return None                     # already a path\n    import winreg\n    for root in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):\n        try:\n            with winreg.OpenKey(\n                    root,\n                    rf\"Software\\Microsoft\\Windows\\CurrentVersion\"\n                    rf\"\\App Paths\\{name}\") as k:\n                v, _ = winreg.QueryValueEx(k, \"\")\n                return str(v)\n        except OSError:\n            continue\n    return None\n\n\ndef _existing_app_window(command: str, wait_title: str = \"\") -> dict[str, Any] | None:\n    wanted = Path(command).name.lower()\n    stem = Path(command).stem.lower()\n    for window in list_windows():\n        process = str(window.get(\"process\") or \"\").lower()\n        title = str(window.get(\"title\") or \"\").strip()\n        if process != wanted and Path(process).stem != stem:\n            continue\n        if title.lower() == stem or (wait_title and wait_title.lower() in title.lower()):\n            return window\n    return None\n\n\ndef open_app(command: str, *, args: list[str] | None = None,\n             wait_title: str | None = None, timeout: float = 20.0,\n             start_minimized: bool = False, urls: list[str] | None = None) -> dict[str, Any]:\n    \"\"\"Launch an application and return the window it actually produced.\n\n    Office apps, Explorer and many others **reuse a running instance**: the\n    process that gets spawned hands the request to the existing one and exits\n    immediately, so its pid owns no window and the document appears in a window\n    whose title nobody predicted. Waiting on the spawned process, or on a title\n    guessed from the file name, therefore hangs for the full timeout while the\n    file is already open on screen — measured here at 120s against Word.\n\n    So the window is found by *diffing* the desktop: snapshot the windows\n    before launching, then watch for one that is new or newly matching. That\n    works for a fresh process and for instance reuse alike, and the result says\n    which happened.\n\n    With the driver, CUA's launch_app starts it (B13); the diff still decides\n    which window the launch produced.\n    \"\"\"\n    global _session_target\n    existing = _existing_app_window(command, wait_title or \"\") if wait_title else None\n    if existing is not None:\n        _session_target = int(existing[\"handle\"])\n        return _result(EffectState.COMMITTED,\n                       pid=int(existing.get(\"pid\") or -1), command=command,\n                       window_handle=int(existing[\"handle\"]), title=str(existing[\"title\"]),\n                       reused_instance=True, quiet_requested=BACKGROUND_ONLY.get())\n    driver = _driver_open_app(command, args=args, wait_title=wait_title, timeout=timeout,\n                              start_minimized=start_minimized, urls=urls)\n    if driver is not None:\n        return driver\n    startup: dict[str, Any] = {}\n    if BACKGROUND_ONLY.get():\n        # Ask Windows to show the new window without activating it. Providers\n        # can ignore startup hints, so report observed foreground changes below.\n        info = subprocess.STARTUPINFO()\n        info.dwFlags |= subprocess.STARTF_USESHOWWINDOW\n        info.wShowWindow = 4  # SW_SHOWNOACTIVATE\n        startup[\"startupinfo\"] = info\n    foreground_before = _foreground_handle()\n    before = _window_index()\n    argv = [command, *(args or [])]\n    try:\n        # Apps validate the inherited working directory: a daemon started\n        # from a dead network path (measured: N:\\) makes Word abort with\n        # 'The directory name is not valid' behind a dialog UIA missed. Spawn\n        # from a guaranteed-local directory instead.\n        cwd = str(Path.home())\n        if not Path(cwd).exists():\n            import tempfile\n            cwd = tempfile.gettempdir()\n        proc = subprocess.Popen(argv, shell=False, cwd=cwd, **startup)\n    except OSError as exc:\n        # Not on PATH (FileNotFoundError) or not an executable at all\n        # (WinError 193 — e.g. a document path): both must reach the\n        # resolution layers below instead of dying here (measured live).\n        # Bare names like \"excel.exe\" live in App Paths, which Popen without\n        # a shell never consults — resolve them the way ShellExecute does\n        # before declaring the app missing (S88: measured live).\n        resolved = _app_path_lookup(command)\n        if resolved:\n            try:\n                proc = subprocess.Popen([resolved, *argv[1:]], shell=False, cwd=cwd, **startup)\n            except Exception as exc2:\n                raise ProtocolError(ErrorCode.APP_LAUNCH_FAILED,\n                                    f\"cannot launch {command!r}: {exc2}\",\n                                    effect_state=EffectState.UNKNOWN) from exc2\n        else:\n            # Store/Uwp apps (Power BI Desktop, Power Automate Desktop...)\n            # have no exe on disk and no App Paths entry — they launch only\n            # through their Start-menu AppID (S95).\n            appid = _start_app_lookup(command)\n            if BACKGROUND_ONLY.get():\n                raise InteractiveRequired(\n                                    \"Quiet launch requires a resolved executable\",\n                                    hint=\"Store apps and shell associations may activate windows.\",\n                                    code=\"background_needs_shell_activation\")\n            if appid:\n                subprocess.Popen([\"explorer.exe\",\n                                  f\"shell:AppsFolder\\\\{appid}\"], shell=False)\n                proc = None          # explorer hands off; the real pid is\n                                     # unknown, and the window diff below\n                                     # finds what appeared anyway\n            else:\n                # Final layer: the device's own shell. Start-Process\n                # resolves PATH, file associations and aliases the layers\n                # above cannot see (user direction S96: PowerShell/CMD is a\n                # legitimate way to recall any local program).\n                quoted = command.replace(\"'\", \"''\")\n                ps = subprocess.run(\n                    [\"powershell\", \"-NoProfile\", \"-Command\",\n                     \"Start-Process -FilePath '{}'\".format(quoted)],\n                    capture_output=True, timeout=25, **hidden())\n                if ps.returncode == 0:\n                    proc = None      # shell handed off; the window diff\n                else:                # below finds what appeared anyway\n                    raise ProtocolError(\n                        ErrorCode.APP_LAUNCH_FAILED,\n                        \"cannot launch {!r}: not found\".format(command),\n                        hint=\"Give a full path, an executable on PATH, or a \"\n                             \"Start-menu app name. Run `auto apps --find \"\n                             \"{!r}` to see what is installed.\".format(command)\n                        ) from exc\n    except Exception as exc:\n        raise ProtocolError(ErrorCode.APP_LAUNCH_FAILED,\n                            f\"cannot launch {command!r}: {exc}\",\n                            effect_state=EffectState.UNKNOWN) from exc\n\n    best = _produced_window(before, wait_title, timeout, command=command)\n    exited = proc is None or proc.poll() is not None\n    if best:\n        # RC-012 fix (2026-10-09): remember the window this launch produced\n        # as the session's intended input target; unaimed keyboard/text input\n        # refuses to deliver into any other foreground window.\n        _session_target = int(best[0])\n        return _result(EffectState.COMMITTED,\n                       pid=(proc.pid if proc else -1), command=command,\n                       window_handle=best[0], title=best[1],\n                       reused_instance=exited,\n                       quiet_requested=BACKGROUND_ONLY.get(),\n                       foreground_changed=foreground_before != _foreground_handle())\n\n    if not wait_title:\n        # Nothing to wait for; the launch itself is the whole request.\n        return _result(EffectState.COMMITTED,\n                       pid=(proc.pid if proc else -1), command=command,\n                       reused_instance=exited)\n\n    raise ProtocolError(\n        ErrorCode.TIMEOUT,\n        f\"{command} launched but no window matching {wait_title!r} appeared \"\n        f\"within {timeout:g}s\"\n        + (\" (the process exited immediately, so it handed off to a running \"\n           \"instance)\" if exited else \"\"),\n        hint=\"Run `auto windows` to see what is open; the app may title the \"\n             \"window differently from the file name.\",\n        effect_state=EffectState.UNKNOWN)\n\n\ndef _produced_window(before: dict[int, Any], wait_title: str | None,\n                     timeout: float, *, command: str = \"\") -> tuple[int, Any] | None:\n    \"\"\"The window a launch produced: new, or retitled, against `before`.\"\"\"\n    needle = (wait_title or \"\").lower()\n    deadline = time.monotonic() + timeout\n    while time.monotonic() < deadline:\n        now = _window_index()\n        fresh = [(h, t) for h, t in now.items()\n                 if t and (h not in before or before.get(h) != t)]\n        if needle:\n            hit = [(h, t) for h, t in fresh if needle in t.lower()]\n            # An existing window that merely changed title counts too: that is\n            # exactly what instance reuse looks like.\n            if not hit:\n                hit = [(h, t) for h, t in now.items()\n                       if needle in t.lower() and before.get(h) != t]\n            if not hit and command:\n                app = Path(command).stem.lower()\n                hit = [(h, t) for h, t in fresh\n                       if t.lower() == app or t.lower().endswith(\" - \" + app)]\n            if hit:\n                return hit[0]\n        elif fresh:\n            return fresh[0]\n        time.sleep(0.25)\n    return None\n\n\n_LAUNCH_DEADLINE_S = 65.0\n\n\ndef _running_pids() -> set[int]:\n    try:\n        import psutil\n        return set(psutil.pids())\n    except Exception:\n        return set()\n\n\ndef _driver_open_app(command: str, *, args: list[str] | None, wait_title: str | None,\n                     timeout: float, start_minimized: bool,\n                     urls: list[str] | None) -> dict[str, Any] | None:\n    \"\"\"B13: CUA's launch_app (impl_.rs:2203-3176 at 815dfd96): no activation,\n    packaged apps by AUMID, AppsFolder / PATH / App Paths by name. CUA joins\n    additional_arguments unquoted (:2508), so each is quoted here. The window\n    diff still names the produced window (CUA's launcher-stub fallback can list\n    a reused instance's existing windows). None keeps the Python path.\"\"\"\n    from . import driver_backend\n    if not driver_backend.supports(\"launch_app\"):\n        if start_minimized or urls:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                \"start_minimized and urls need the driver's launch_app; nothing was launched\",\n                effect_state=EffectState.NONE)\n        return None\n    if Path(command).is_file():\n        params: dict[str, Any] = {\"path\": command}\n    elif \"!\" in command:\n        params = {\"aumid\": command}\n    else:\n        params = {\"name\": command}\n    if args:\n        params[\"additional_arguments\"] = [subprocess.list2cmdline([str(a)]) for a in args]\n    if start_minimized:\n        params[\"start_minimized\"] = True\n    if urls:\n        params[\"urls\"] = [str(u) for u in urls]\n    foreground_before = _foreground_handle()\n    before = _window_index()\n    pids_before = _running_pids()\n    # Above the adapter's 60 s launch deadline, so its own answer arrives first.\n    reply = driver_backend.try_call(\"launch_app\", params,\n                                    deadline=time.monotonic() + _LAUNCH_DEADLINE_S)\n    if reply is None:\n        return None                 # the driver went away before the call: nothing was sent\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.APP_LAUNCH_FAILED,\n            f\"cannot launch {command!r}: {error.get('message') or error.get('code')}\",\n            hint=\"Give a full path, an executable on PATH, a Start-menu app name \"\n                 \"or an AUMID. Run `auto apps --find` to see what is installed.\",\n            effect_state=EffectState.NONE if error.get(\"effect_state\") == \"none\"\n            else EffectState.UNKNOWN)\n    res = reply.get(\"result\") or {}\n    pid = int(res.get(\"pid\") or -1)\n    bundle_id = res.get(\"bundle_id\")\n    # A packaged app's window belongs to the shared ApplicationFrameHost\n    # (:2859-2881); a pid that already ran is a reused instance. Reset must\n    # record neither for cleanup (runcleanup.windows_to_close).\n    reused = bool(bundle_id) or pid in pids_before\n    needle = (wait_title or \"\").lower()\n    best = None\n    for w in res.get(\"windows\") or []:\n        h, t = int(w.get(\"window_id\") or 0), str(w.get(\"title\") or \"\")\n        if h and t and before.get(h) != t and (not needle or needle in t.lower()):\n            best = (h, t)\n            break\n    if best is None:\n        best = _produced_window(before, wait_title, timeout, command=command)\n    extra = {\"via\": \"driver-launch_app\", \"bundle_id\": bundle_id}\n    if best:\n        global _session_target\n        _session_target = int(best[0])            # RC-012, as on the Python path\n        return _result(EffectState.COMMITTED, pid=pid, command=command,\n                       window_handle=best[0], title=best[1], reused_instance=reused,\n                       quiet_requested=BACKGROUND_ONLY.get(),\n                       foreground_changed=foreground_before != _foreground_handle(), **extra)\n    if not wait_title:\n        return _result(EffectState.COMMITTED, pid=pid, command=command,\n                       reused_instance=reused, **extra)\n    raise ProtocolError(\n        ErrorCode.TIMEOUT,\n        f\"{command} launched but no window matching {wait_title!r} appeared within {timeout:g}s\",\n        hint=\"Run `auto windows` to see what is open; the app may title the \"\n             \"window differently from the file name.\",\n        effect_state=EffectState.UNKNOWN)\n\n\ndef close_window(title_substring: str) -> dict[str, Any]:\n    w = find_window(title_substring)\n    if w is None:\n        raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND,\n                            f\"no window matching {title_substring!r}\")\n    title = _safe(lambda: w.Name, \"\") or \"\"\n    handle = _safe(lambda: w.NativeWindowHandle, 0) or 0\n    wp = _safe(lambda: w.GetWindowPattern(), None)\n    if wp is None or not _safe(lambda: (wp.Close(), True)[1], False):\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED, f\"could not close {title!r}\",\n            hint=\"The window may be showing a modal dialog; observe it first.\",\n            effect_state=EffectState.UNKNOWN)\n    # A close can be acked and then nothing happens: an Office document under\n    # an OneDrive/telemetry lock acks Close and stays put (ledger R26/R29), a\n    # wedged dialog does the same. Verify the window is really gone before\n    # calling it done, and if it refuses, name the process holding it.\n    time.sleep(0.8)\n    if handle and find_window(f\"#{handle}\") is not None:\n        time.sleep(1.7)\n        if find_window(f\"#{handle}\") is not None:\n            return _result(EffectState.UNKNOWN, title=title,\n                           method=\"window_pattern\", zombie=True,\n                           process=_process_name(w),\n                           note=\"close was acknowledged but the window is still \"\n                                \"present — a background lock (Office/OneDrive) \"\n                                \"is likely. `auto quit-app` ends the process.\")\n    return _result(EffectState.COMMITTED, title=title, method=\"window_pattern\")\n\n\n# How to drive each class of application — carried with the inventory so\n# any agent on any device gets the strategy inline, not from memory.\nAPP_CLASS_STRATEGIES = {\n    \"win32\": \"Full UIA automation: open-app -> observe -> click/type -> \"\n             \"verify. Win11 common dialogs may need real input (--real); \"\n             \"watch the screen (screenshot) when state matters.\",\n    \"uwp\": \"Launch by Start-menu name (open-app resolves the AppID). UIA \"\n           \"trees are often sparse: prefer real clicks, keyboard, and \"\n           \"visual verification; check the window title for state.\",\n    \"menu\": \"Start-menu classic entry: launch by name, then drive as win32.\",\n}\n\n\ndef _classify(appid: str | None, install_loc: str | None) -> str:\n    \"\"\"Evidence over guesswork: package-style AppIDs mark Store apps;\n    a WindowsApps install location marks them even without one.\"\"\"\n    if appid and \"!\" in appid:\n        return \"uwp\"\n    loc = (install_loc or \"\").lower()\n    if \"windowsapps\" in loc:\n        return \"uwp\"\n    return \"win32\"\n\n\ndef _list_apps_python() -> dict[str, dict[str, str]]:\n    \"\"\"The Python registries walk (b16: extracted from installed_apps\n    verbatim — the `_list_windows_python` refactor precedent). Three\n    registries of truth, merged and deduped: Start menu (Get-StartApps),\n    Uninstall keys, App Paths. Returns the lower-name -> row map; the\n    caller sorts/filters/envelopes.\"\"\"\n    import json as _json\n    out: dict[str, dict[str, str]] = {}      # lower name -> {name, kind, cls}\n\n    def add(name: str, kind: str, cls: str = \"win32\") -> None:\n        key = (name or \"\").strip().lower()\n        if not key:\n            return\n        if key in out:                        # richer evidence wins\n            if cls == \"uwp\" and out[key][\"cls\"] != \"uwp\":\n                out[key][\"cls\"] = \"uwp\"\n            return\n        out[key] = {\"name\": name.strip(), \"kind\": kind, \"cls\": cls}\n\n    # 1. Start menu: Store apps and pinned/classic entries (launchable now).\n    try:\n        r = subprocess.run(\n            [\"powershell\", \"-NoProfile\", \"-Command\",\n             \"Get-StartApps | ConvertTo-Json -Compress\"],\n            capture_output=True, timeout=25, check=True, **hidden())\n        apps = _json.loads(r.stdout.decode(\"utf-8\", \"replace\") or \"[]\")\n        if isinstance(apps, dict):\n            apps = [apps]\n        for a in apps:\n            add(a.get(\"Name\") or \"\", \"start\",\n                _classify(a.get(\"AppID\"), None))\n    except Exception:\n        pass\n\n    # 2. Uninstall registry: everything with an installer (may or may not\n    #    be start-launchable, but it IS installed).\n    import winreg\n    for root, sub in ((winreg.HKEY_LOCAL_MACHINE,\n                       r\"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\"),\n                      (winreg.HKEY_LOCAL_MACHINE,\n                       r\"SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\"),\n                      (winreg.HKEY_CURRENT_USER,\n                       r\"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\")):\n        try:\n            k = winreg.OpenKey(root, sub)\n        except OSError:\n            continue\n        with k:\n            for i in range(winreg.QueryInfoKey(k)[0]):\n                try:\n                    with winreg.OpenKey(k, winreg.EnumKey(k, i)) as sk:\n                        name, _ = winreg.QueryValueEx(sk, \"DisplayName\")\n                        try:\n                            loc, _ = winreg.QueryValueEx(sk, \"InstallLocation\")\n                        except OSError:\n                            loc = None\n                except OSError:\n                    continue\n                add(str(name), \"installed\", _classify(None, loc))\n\n    # 3. App Paths: bare names Popen misses but the shell resolves.\n    for root in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):\n        try:\n            k = winreg.OpenKey(\n                root,\n                r\"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\")\n        except OSError:\n            continue\n        with k:\n            for i in range(winreg.QueryInfoKey(k)[0]):\n                try:\n                    add(winreg.EnumKey(k, i), \"app-path\")\n                except OSError:\n                    break\n    return out\n\n\ndef _driver_app_rows() -> list[dict[str, Any]] | None:\n    \"\"\"b16: CUA's list_apps rows, merged into AutoSkill's public row shape\n    (impl_.rs:692-876 at pin 815dfd96). None = unavailable/refused/malformed\n    -> the caller fails open to the Python inventory (the list_windows\n    precedent: an inventory sends no input). The merge keeps the public\n    three keys {name, kind, cls} and ADDS CUA's keys {pid, bundle_id,\n    running, active, launch_path, last_used}; CUA's packaging kind maps\n    onto cls (\"uwp\"->\"uwp\", \"desktop\"->\"win32\") — it never lands as a key;\n    windows (always [] on Windows) and the legacy processes array never\n    surface. A running row with no launch_path has no start entry, so its\n    evidence-source kind is \"installed\" (inside the strict ApplicationKind\n    enum, contracts/environment.py).\"\"\"\n    from . import driver_backend\n    # An EXPLICIT deadline: CUA's own canonical runner budgets list_apps\n    # at 8 s (protocol_tools_call_test.rs:53-57) and the backend default is\n    # 5.0 s — a cold WinRT PackageManager scan must not spuriously fail\n    # open (S1 5b).\n    reply = driver_backend.try_call(\n        \"list_apps\", {}, deadline=time.monotonic() + 20.0)\n    if reply is None or not reply.get(\"ok\"):\n        return None\n    apps = (reply.get(\"result\") or {}).get(\"apps\")\n    if not isinstance(apps, list):\n        return None                    # malformed: fail open\n    rows: list[dict[str, Any]] = []\n    for row in apps:\n        if not isinstance(row, dict):\n            continue                   # malformed row: skip\n        name = row.get(\"name\")\n        if not isinstance(name, str) or not name.strip():\n            continue\n        running = bool(row.get(\"running\"))\n        launch_path = row.get(\"launch_path\")\n        launch_path = launch_path if isinstance(launch_path, str) else None\n        merged: dict[str, Any] = {\n            \"name\": name.strip(),\n            \"kind\": (\"installed\" if running and launch_path is None\n                     else \"start\"),\n            \"cls\": \"uwp\" if row.get(\"kind\") == \"uwp\" else \"win32\",\n        }\n        # The additive CUA keys (the plan rule: keep the public row shape;\n        # add CUA keys as additive keys).\n        pid = row.get(\"pid\")\n        merged[\"pid\"] = pid if isinstance(pid, int) else 0\n        bundle_id = row.get(\"bundle_id\")\n        merged[\"bundle_id\"] = bundle_id if isinstance(bundle_id, str) else None\n        merged[\"running\"] = running\n        merged[\"active\"] = bool(row.get(\"active\"))\n        merged[\"launch_path\"] = launch_path\n        last_used = row.get(\"last_used\")\n        merged[\"last_used\"] = last_used if isinstance(last_used, str) else None\n        rows.append(merged)\n    return rows\n\n\ndef installed_apps(find: str | None = None,\n                   cls: str | None = None,\n                   via_driver: bool = True) -> dict[str, Any]:\n    \"\"\"Deep inventory of launchable programs on this device.\n\n    b16: driver-first fail-open (the list_windows precedent verbatim) —\n    with the driver enabled, CUA's list_apps serves the inventory (rows\n    carry pid/running/active/bundle_id/launch_path/last_used additively);\n    an unavailable/refusing/old-exe driver fails open to EXACTLY today's\n    three-registry Python walk (an inventory sends no input, plan 0.3.3).\n    The public row shape and envelope are unchanged on both paths.\n    \"\"\"\n    rows = None\n    # No supports() pre-gate: the capability refusal arrives as\n    # unsupported_method through the seam and fails open below (an OLD exe\n    # keeps the Python inventory; a driver-off transport returns None).\n    if via_driver:\n        rows = _driver_app_rows()\n    if rows is not None:\n        out_rows = rows\n    else:\n        out_rows = list(_list_apps_python().values())\n    items = sorted(out_rows, key=lambda d: d[\"name\"].lower())\n    if find:\n        needle = find.lower()\n        items = [d for d in items if needle in d[\"name\"].lower()]\n    if cls:\n        want = cls.lower()\n        items = [d for d in items if d[\"cls\"] == want]\n    return {\"count\": len(items), \"total\": len(out_rows), \"apps\": items,\n            \"strategies\": APP_CLASS_STRATEGIES,\n            \"effect_state\": EffectState.NONE.value}\n\n\ndef _pids_by_name(process_name: str) -> list[int]:\n    \"\"\"Pids of live processes matching a name (case-insensitive, with or\n    without the .exe suffix). Tiny on purpose so tests can replace it.\"\"\"\n    import psutil\n    needle = process_name.lower().removesuffix(\".exe\")\n    out: list[int] = []\n    for p in psutil.process_iter([\"name\"]):\n        try:\n            if (p.info.get(\"name\") or \"\").lower().removesuffix(\".exe\") == needle:\n                out.append(p.pid)\n        except Exception:\n            continue\n    return out\n\n\ndef _pid_alive(pid: int) -> bool:\n    import psutil\n    return psutil.pid_exists(pid)\n\n\ndef _driver_kill_app(pid: int) -> dict[str, Any] | None:\n    \"\"\"B15: invoke pinned CUA KillAppTool; a text acknowledgement still needs an exit check.\"\"\"\n    from . import driver_backend\n    if not driver_backend.supports(\"kill_app\"):\n        return None\n    foreground_before, cursor_before = _foreground_handle(), _cursor_pos()\n    reply = driver_backend.try_call(\"kill_app\", {\"pid\": pid})\n    if reply is None:\n        return None\n    observed = {\"foreground_changed\": _foreground_handle() != foreground_before,\n                \"cursor_moved\": _cursor_pos() != cursor_before}\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        exc = ProtocolError(ErrorCode.INTERNAL, str(error.get(\"message\") or error.get(\"code\")),\n                            effect_state=EffectState.NONE if error.get(\"effect_state\") == \"none\"\n                            else EffectState.UNKNOWN)\n        exc.error.details = {\"driver_code\": error.get(\"code\"), **observed}\n        raise exc\n    gone = not _safe(lambda: _pid_alive(pid), True)\n    return _result(EffectState.COMMITTED if gone else EffectState.UNKNOWN,\n                   pid=pid, pids=[pid], forced=True, via=\"driver-kill_app\",\n                   summary=(reply.get(\"result\") or {}).get(\"summary\"), **observed)\n\n\ndef quit_app(process_name: str = \"\", *, pid: int | None = None,\n             timeout: float = 12.0) -> dict[str, Any]:\n    \"\"\"Close every window of a named app, then end its leftover processes.\n\n    The revenge of instance-reusing apps (ledger R29): Word is \"closed\", its\n    windows are gone, and the file is still locked by a headless background\n    WINWORD.EXE that owns nothing visible. Graceful first — close windows,\n    wait out the timeout — and only then terminate, saying so in the result.\n    \"\"\"\n    if pid is not None:\n        if process_name or type(pid) is not int or not 0 < pid <= 0xFFFFFFFF:\n            raise ProtocolError(ErrorCode.UNSUPPORTED, \"provide either a process name or a positive integer pid\")\n        driver = _driver_kill_app(pid)\n        if driver is not None:\n            return driver\n        # Driver off or unavailable before dispatch: retain an exact-PID Python path.\n        import psutil\n        try:\n            proc = psutil.Process(pid)\n            proc.kill()\n            psutil.wait_procs([proc], timeout=3)\n        except psutil.NoSuchProcess:\n            return _result(EffectState.NONE, pid=pid, note=\"process is no longer running\")\n        except Exception as exc:\n            raise ProtocolError(ErrorCode.INTERNAL, str(exc), effect_state=EffectState.UNKNOWN) from exc\n        return _result(EffectState.UNKNOWN if _safe(lambda: _pid_alive(pid), True) else EffectState.COMMITTED,\n                       pid=pid, pids=[pid], forced=True)\n    if not process_name:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"provide a process name or pid\")\n    pids = _pids_by_name(process_name)\n    if not pids:\n        return _result(EffectState.NONE, process=process_name,\n                       note=\"no live process matches; nothing to do\")\n    ua = _require_uia()\n    closed = 0\n    for w in _safe(lambda: ua.GetRootControl().GetChildren(), []) or []:\n        if _safe(lambda w=w: w.ProcessId, None) in pids:\n            wp = _safe(lambda w=w: w.GetWindowPattern(), None)\n            if wp is not None and _safe(lambda p=wp: (p.Close(), True)[1], False):\n                closed += 1\n\n    deadline = time.monotonic() + timeout\n    while time.monotonic() < deadline:\n        if not any(_pid_alive(p) for p in pids):\n            return _result(EffectState.COMMITTED, process=process_name,\n                           pids=pids, windows_closed=closed, forced=False)\n        time.sleep(0.5)\n\n    # The zombie survivors: acked every close, outlived the grace period.\n    import psutil\n    procs = []\n    for p in pids:\n        if _pid_alive(p):\n            try:\n                procs.append(psutil.Process(p))\n            except Exception:\n                pass            # gone between the check and here: done anyway\n    python_procs = []\n    driver_results = []\n    for p in procs:\n        try:\n            driver = _driver_kill_app(p.pid)\n        except ProtocolError as exc:\n            if closed or driver_results:\n                exc.error.effect_state = EffectState.UNKNOWN\n            raise\n        if driver is None:\n            python_procs.append(p)\n        else:\n            driver_results.append(driver)\n    for p in python_procs:\n        try:\n            p.terminate()\n        except Exception:\n            pass\n    psutil.wait_procs(python_procs, timeout=3)\n    for p in python_procs:\n        if p.is_running():\n            try:\n                p.kill()\n            except Exception:\n                pass\n    if python_procs or not driver_results:\n        time.sleep(0.5)\n    still = [p.pid for p in procs if _pid_alive(p.pid)]\n    driver_details = ({\"via\": \"driver-kill_app\", \"foreground_changed\": any(\n        r[\"foreground_changed\"] for r in driver_results), \"cursor_moved\": any(\n        r[\"cursor_moved\"] for r in driver_results)} if driver_results else {})\n    if still:\n        return _result(EffectState.UNKNOWN, process=process_name, pids=still,\n                       windows_closed=closed, forced=True,\n                       note=\"process(es) survived terminate and kill\", **driver_details)\n    return _result(EffectState.COMMITTED, process=process_name, pids=pids,\n                   windows_closed=closed, forced=True,\n                   note=\"graceful close did not end the process; it was \"\n                        \"terminated to release its file locks\", **driver_details)\n\n\n# --- files --------------------------------------------------------------------\n\n_FOF_SILENT = 0x4\n_FOF_NOCONFIRMATION = 0x10\n_FOF_ALLOWUNDO = 0x40\n_FOF_NOERRORUI = 0x400\n\n\ndef copy_paths(sources: list[str], destination: str) -> dict[str, Any]:\n    \"\"\"Copy files or directories with Explorer's semantics, no UI.\n\n    R28: the tool had no file verb, so \"save a copy of this next to that\"\n    meant driving Explorer's window by hand — slow and fragile where one\n    shell call is exact. SHFileOperation keeps OneDrive placeholder\n    behaviour and recycle-bin semantics intact.\n    \"\"\"\n    import ctypes\n    from ctypes import wintypes\n\n    if not sources:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED, \"copy needs at least one source and a \"\n            \"destination (auto copy SRC... DEST)\")\n\n    class _SHFILEOPSTRUCTW(ctypes.Structure):\n        _fields_ = [(\"hwnd\", wintypes.HWND),\n                    (\"wFunc\", ctypes.c_uint),\n                    (\"pFrom\", ctypes.c_wchar_p),\n                    (\"pTo\", ctypes.c_wchar_p),\n                    (\"fFlags\", ctypes.c_ushort),\n                    (\"fAnyOperationsAborted\", wintypes.BOOL),\n                    (\"hNameMappings\", ctypes.c_void_p),\n                    (\"lpszProgressTitle\", ctypes.c_wchar_p)]\n\n    srcs = [str(Path(s)) for s in sources]\n    dst = str(Path(destination))\n    for s in srcs:\n        if not Path(s).exists():\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_FOUND, f\"source not found: {s}\",\n                hint=\"Check the path; wildcards are allowed per Explorer \"\n                     \"rules only with a single source.\")\n\n    # The API wants double-null-terminated lists; c_wchar_p appends the\n    # final NUL, so each list gets one explicit trailing NUL.\n    op = _SHFILEOPSTRUCTW()\n    op.wFunc = 2                      # FO_COPY\n    op.pFrom = \"\\0\".join(srcs) + \"\\0\"\n    op.pTo = dst + \"\\0\"\n    op.fFlags = _FOF_SILENT | _FOF_NOCONFIRMATION | _FOF_ALLOWUNDO | _FOF_NOERRORUI\n    res = ctypes.windll.shell32.SHFileOperationW(ctypes.byref(op))\n    if res != 0 or op.fAnyOperationsAborted:\n        raise ProtocolError(\n            ErrorCode.INTERNAL, f\"copy failed (code {res})\",\n            hint=\"Check that the destination folder exists and is writable.\",\n            effect_state=EffectState.NONE)\n    return _result(EffectState.COMMITTED, sources=srcs, destination=dst)\n\n\n# --- screenshot --------------------------------------------------------------\n\ndef _raise_and_verify(window: Any, selector: str, attempts: int = 3) -> None:\n    \"\"\"Bring a window to the front and **confirm** it got there.\n\n    A region screenshot captures whatever pixels occupy those screen\n    coordinates. If the target did not actually come forward, the file contains\n    a different application entirely — and the call still reports success.\n    That happened: a capture of an Excel workbook returned the chat window that\n    was sitting on top of it.\n\n    Windows refuses foreground changes from a background process in several\n    situations (focus-stealing prevention, a modal elsewhere, a full-screen\n    app), so this must be verified rather than assumed.\n    \"\"\"\n    require_interactive(\"Raising a window\")\n    import ctypes\n    target = _safe(lambda: window.NativeWindowHandle, 0) or 0\n    for attempt in range(attempts):\n        _force_foreground(target)\n        _safe(lambda: window.SetActive())\n        _safe(lambda: window.SetFocus())\n        if target:\n            _safe(lambda: ctypes.windll.user32.SetForegroundWindow(target))\n        time.sleep(0.25 + 0.2 * attempt)\n        try:\n            front = ctypes.windll.user32.GetForegroundWindow()\n        except Exception:\n            return  # cannot verify; do not block the capture\n        if not target or front == target:\n            time.sleep(0.15)     # let it finish painting\n            return\n\n    front_title = \"\"\n    try:\n        buf = ctypes.create_unicode_buffer(256)\n        ctypes.windll.user32.GetWindowTextW(front, buf, 256)\n        front_title = buf.value\n    except Exception:\n        pass\n    raise ProtocolError(\n        ErrorCode.TARGET_NOT_VISIBLE,\n        f\"{selector!r} could not be brought to the front; \"\n        f\"{front_title or 'another window'} is on top\",\n        hint=\"A capture now would contain the wrong window. Click the target \"\n             \"window yourself, or close whatever is covering it, then retry.\")\n\n\ndef screenshot(out_path: Path, *, store: RefStore | None = None,\n               ref: str | None = None, window: str | None = None) -> dict[str, Any]:\n    with foreground_returned():\n        return _screenshot_inner(out_path, store=store, ref=ref,\n                                 window=window)\n\n\ndef _screenshot_inner(out_path: Path, *, store: RefStore | None = None,\n                      ref: str | None = None,\n                      window: str | None = None) -> dict[str, Any]:\n    if BACKGROUND_ONLY.get() and (window or (ref and store is not None)):\n        from .background_capture import capture_window\n        crop = None\n        if ref and store is not None:\n            entry = store.resolve(ref)\n            _guard(entry)\n            w = find_window(entry.window_title) if entry.window_title else None\n            if w is None:\n                raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND,\n                                    \"The element's owning window cannot be resolved\")\n            r = entry.control.BoundingRectangle\n            crop = (r.left, r.top, r.right, r.bottom)\n        else:\n            w = find_window(window or \"\")\n        if w is None:\n            raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND, f\"no window matching {window!r}\")\n        result = capture_window(int(w.NativeWindowHandle), out_path, crop=crop)\n        return _result(EffectState.NONE, target=str(w.Name), **result)\n    try:\n        import mss\n        import mss.tools\n    except ImportError as exc:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"mss is not installed\") from exc\n\n    region: dict[str, int] | None = None\n    label = \"screen\"\n    if ref and store is not None:\n        entry = store.resolve(ref)\n        _guard(entry)\n        # An element capture is a region capture too: if its window is behind\n        # something else, the pixels belong to that something else.\n        if entry.window_title:\n            win = _safe(lambda: find_window(entry.window_title), None)\n            if win is not None:\n                _raise_and_verify(win, entry.window_title)\n        _safe(lambda: entry.control.ScrollIntoView())\n        r = _safe(lambda: entry.control.BoundingRectangle, None)\n        if r is None:\n            raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                                f\"{entry.describe()} has no visible area\")\n        region = {\"left\": r.left, \"top\": r.top,\n                  \"width\": r.right - r.left, \"height\": r.bottom - r.top}\n        label = entry.describe()\n    elif window:\n        w = find_window(window)\n        if w is None:\n            raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND,\n                                f\"no window matching {window!r}\")\n        _raise_and_verify(w, window)\n        r = _safe(lambda: w.BoundingRectangle, None)\n        if r:\n            region = {\"left\": r.left, \"top\": r.top,\n                      \"width\": r.right - r.left, \"height\": r.bottom - r.top}\n        label = _safe(lambda: w.Name, \"\") or window\n\n    out_path.parent.mkdir(parents=True, exist_ok=True)\n    # Self-exclusion: the agent cursor must not photograph itself into the\n    # captures the agent takes to observe its own work. Fail-open, like\n    # every overlay interaction.\n    from ..dashboard.windows import make_way\n    with overlay.hidden_for_capture(), make_way():     # neither marker nor dashboard in the picture\n        with mss.mss() as sct:\n            shot = sct.grab(region or sct.monitors[0])\n            mss.tools.to_png(shot.rgb, shot.size, output=str(out_path))\n    return _result(EffectState.NONE, path=str(out_path), target=label,\n                   width=shot.size[0], height=shot.size[1],\n                   bytes=out_path.stat().st_size)\n\n\n# --- waiting -----------------------------------------------------------------\n\ndef wait_for_window(selector: str, *, timeout: float = 20.0,\n                    gone: bool = False) -> dict[str, Any]:\n    \"\"\"Block until a window appears (or disappears).\n\n    Without this an agent has to poll in a shell loop, which is slower, noisier\n    and races with its own observations.\n    \"\"\"\n    deadline = time.monotonic() + timeout\n    while time.monotonic() < deadline:\n        try:\n            if selector.strip().startswith(\"#\"):\n                found = _window_identity(int(selector.strip()[1:], 0)) is not None\n            else:\n                rows = _driver_window_rows()\n                if rows is not None:\n                    needle = selector.strip().lower()\n                    found = any(needle in str(row.get(\"title\") or \"\").lower() for row in rows)\n                else:\n                    found = bool(_win32_windows_matching(selector.strip().lower()))\n        except (ProtocolError, ValueError):\n            found = True          # ambiguous means at least one exists\n        if found != gone:\n            return _result(EffectState.NONE, selector=selector,\n                           waited_s=round(timeout - (deadline - time.monotonic()), 2),\n                           state=\"gone\" if gone else \"present\")\n        time.sleep(0.2)\n    raise ProtocolError(\n        ErrorCode.TIMEOUT,\n        f\"window {selector!r} did not \"\n        f\"{'disappear' if gone else 'appear'} within {timeout:g}s\",\n        hint=\"Run `auto windows` to see what is actually open.\")\n\n\ndef wait_for_ref(store: RefStore, name_substring: str, *,\n                 window: str | None = None, timeout: float = 20.0) -> dict[str, Any]:\n    \"\"\"Block until an element whose name contains `name_substring` is present.\n\n    Re-observes on each poll, so the returned ref is fresh by construction.\n    \"\"\"\n    from . import uia\n    needle = name_substring.lower()\n    deadline = time.monotonic() + timeout\n    last_error: str | None = None\n    while time.monotonic() < deadline:\n        try:\n            target = find_window(window) if window else None\n            if window and target is None:\n                last_error = f\"window {window!r} not found\"\n            else:\n                ctl = target or _require_uia().GetForegroundControl()\n                uia.observe(ctl, store, process=_process_name(ctl),\n                            window_title=_safe(lambda: ctl.Name, \"\") or \"\")\n                for entry in store.snapshot():\n                    if needle in entry[\"name\"].lower():\n                        return _result(EffectState.NONE, ref=entry[\"ref\"],\n                                       name=entry[\"name\"], role=entry[\"role\"])\n        except ProtocolError as exc:\n            last_error = exc.error.message\n        time.sleep(0.3)\n    raise ProtocolError(\n        ErrorCode.TIMEOUT,\n        f\"no element matching {name_substring!r} appeared within {timeout:g}s\"\n        + (f\" ({last_error})\" if last_error else \"\"),\n        hint=\"Observe to see what is on screen; the name may differ.\")\n");
